/* Sơ đồ và diễn giải tự biên soạn, liên kết tới các mục học có nguồn. */
window.NET_MODELS=[{"id":"layers","chapter":"1","section":"1.4","title":"Phòng thủ nhiều lớp: một lỗ hổng chưa phải toàn bộ hệ thống","intro":"Theo dõi một file tải từ Internet đến máy người dùng: mỗi lớp giải quyết một loại rủi ro khác nhau.","nodes":[{"id":"net","slot":"a","label":"Internet","caption":"Nguồn bên ngoài","definition":"Nguồn gửi dữ liệu có thể hợp lệ hoặc không; cần kiểm tra thay vì mặc định tin cậy."},{"id":"fw","slot":"b","label":"Firewall","caption":"Kiểm soát luồng","definition":"Tường lửa quyết định luồng nào được phép đi qua theo chính sách và khả năng kiểm tra của nó."},{"id":"host","slot":"c","label":"Máy người dùng","caption":"Kiểm tra đầu cuối","definition":"Endpoint protection quan sát file, tiến trình và hành vi trên máy, kể cả nội dung đã được giải mã ở đầu cuối."},{"id":"rights","slot":"f","label":"Quyền tối thiểu","caption":"Giới hạn thiệt hại","definition":"Least privilege chỉ cấp quyền cần thiết; một tài khoản thường không nên sửa mọi thành phần hệ thống."},{"id":"recover","slot":"e","label":"Sao lưu & ứng phó","caption":"Khôi phục","definition":"Bản sao lưu sạch và quy trình ứng phó giúp khôi phục sau khi biện pháp ngăn chặn thất bại."}],"edges":[{"id":"a","fromId":"net","toId":"fw","label":"1 · kết nối"},{"id":"b","fromId":"fw","toId":"host","label":"2 · được phép"},{"id":"c","fromId":"host","toId":"rights","label":"3 · thực thi"},{"id":"d","fromId":"rights","toId":"recover","label":"4 · xử lý"}],"steps":[{"title":"Kiểm tra đường vào","body":"Firewall xem luồng kết nối có đúng chính sách hay không. Cho phép HTTPS nghĩa là cho phép một loại luồng; nó không chứng minh mọi file bên trong đều lành tính. HTTPS bảo vệ kênh truyền, không chứng nhận ý định của nội dung.","edges":["a"]},{"title":"Kiểm tra nơi dữ liệu được sử dụng","body":"File đến máy và được giải mã tại ứng dụng. Công cụ bảo vệ đầu cuối có thể kiểm tra file, chữ ký hoặc hành vi. Một lớp cần quan sát thứ mà lớp trước không thấy, thay vì chỉ lặp lại cùng một kiểm tra.","edges":["b"]},{"title":"Giảm quyền mà mã có thể sử dụng","body":"Nếu file độc hại vẫn chạy, nó hoạt động trong bối cảnh quyền của tiến trình/tài khoản và các kiểm soát hệ điều hành. Quyền thấp làm giảm phạm vi tác động, nhưng không ngăn mọi hành vi: dữ liệu người dùng được phép đọc vẫn có thể bị ảnh hưởng.","edges":["c"]},{"title":"Khôi phục và rút kinh nghiệm","body":"Khi phát hiện sự cố, cô lập, giữ bằng chứng cần thiết, xác định phạm vi rồi khôi phục từ nguồn sạch. Sao lưu chỉ hữu ích nếu bản sao không cùng bị phá và đã thử phục hồi. Đây là lớp giảm hậu quả, không thay thế việc phòng ngừa.","edges":["d"]}],"example":"Một file độc hại đi qua kết nối HTTPS được cho phép. Endpoint có thể chặn nó; nếu không, quyền tối thiểu hạn chế tác động và bản sao lưu hỗ trợ phục hồi. Không lớp nào đơn độc bảo đảm kết quả.","limits":"Hình là chuỗi kiểm soát minh họa, không phải mọi gói tin đi qua một thiết bị mang tên “quyền tối thiểu”. Trong thực tế các lớp còn song song, chồng lấp và phụ thuộc cấu hình.","mistakes":["Firewall không đồng nghĩa antivirus.","Mã hóa không tự loại bỏ malware.","Sao lưu là khả năng phục hồi, không phải bằng chứng chưa bị xâm nhập."],"check":{"question":"Firewall đã cho phép HTTPS; tại sao vẫn cần bảo vệ đầu cuối?","answer":"Vì đầu cuối thấy nội dung/hành vi sau giải mã, trong khi quyết định cho phép luồng không chứng minh file là an toàn."},"refs":[],"deep":[]},{"id":"replay","chapter":"1","section":"1.2.3","title":"Replay: thông điệp đúng nhưng bị dùng lại","intro":"Phân biệt kiểm tra “ai gửi, có bị sửa không” với kiểm tra “thông điệp có còn mới không”.","nodes":[{"id":"alice","slot":"a","label":"Người gửi","caption":"Thông điệp có tag","definition":"Người gửi hợp lệ tạo yêu cầu có MAC hoặc chữ ký."},{"id":"wire","slot":"b","label":"Đường truyền","caption":"Bản tin có thể bị ghi lại","definition":"Đối phương có thể ghi lại nguyên một thông điệp mà không cần giải mã hoặc thay đổi nó."},{"id":"server","slot":"c","label":"Máy nhận","caption":"Kiểm tra & xử lý","definition":"Máy nhận kiểm tra tính xác thực, tính mới và quyền thực hiện trước khi tác động trạng thái."},{"id":"record","slot":"e","label":"Bản tin cũ","caption":"Gửi lại nguyên vẹn","definition":"Bản ghi giữ nguyên dữ liệu và tag nên kiểm tra xác thực đơn thuần có thể vẫn đạt."}],"edges":[{"id":"send","fromId":"alice","toId":"wire","label":"1"},{"id":"accept","fromId":"wire","toId":"server","label":"2"},{"id":"copy","fromId":"wire","toId":"record","label":"3 · ghi lại"},{"id":"repeat","fromId":"record","toId":"server","label":"4 · gửi lại"}],"steps":[{"title":"Tạo một yêu cầu hợp lệ","body":"Alice gửi yêu cầu có dữ liệu và tag xác thực. Tag giúp phát hiện dữ liệu bị sửa và chứng minh người tạo biết khóa phù hợp; tự nó chưa cho biết yêu cầu này đã được xử lý lần nào.","edges":["send"]},{"title":"Máy nhận kiểm tra lần đầu","body":"Nếu tag đúng và người gửi có quyền, yêu cầu được thực hiện. Nếu giao thức chưa ràng buộc một số thứ tự hay giá trị mới vào phần được xác thực, máy nhận có thể không có dấu hiệu phân biệt lần sau với lần đầu.","edges":["accept"]},{"title":"Ghi lại không đồng nghĩa bẻ khóa","body":"Đối phương giữ nguyên bản tin hợp lệ đã đi qua. Không cần biết plaintext nếu có thể chuyển lại toàn bộ thông điệp được giao thức chấp nhận. Đây là lý do bảo mật nội dung và chống phát lại là hai vấn đề khác nhau.","edges":["copy"]},{"title":"Kiểm tra tính mới trước khi thực hiện","body":"Lần gửi lại phải bị loại bằng nonce dùng một lần, số thứ tự/cửa sổ chống replay hoặc timestamp kết hợp kiểm tra phù hợp. Giá trị chống replay phải được ràng buộc vào MAC/chữ ký và máy nhận phải ghi nhận trạng thái; chỉ thêm một trường không kiểm tra là chưa đủ.","edges":["repeat"]}],"example":"Một lệnh “thực hiện giao dịch X” đã có tag đúng không nên gây tác động lần hai. Mã giao dịch duy nhất và cơ chế xử lý idempotent có thể bổ sung cho chống replay của giao thức.","limits":"Đây là mô hình logic; chi tiết nonce, đồng hồ và replay cache tùy giao thức. Không coi mọi gói lặp do mạng truyền lại là hành vi tấn công.","mistakes":["Tag vẫn đúng không có nghĩa thông điệp còn mới.","Timestamp không tự chống replay trong toàn bộ khoảng thời gian được chấp nhận."],"check":{"question":"Tại sao mã hóa yêu cầu vẫn chưa chắc chống replay?","answer":"Vì người ngoài có thể phát lại nguyên ciphertext mà không cần đọc nội dung; máy nhận còn phải kiểm tra tính mới."},"refs":[],"deep":[]},{"id":"trojan","chapter":"2a","section":"2a.2","title":"Trojan: từ vỏ bọc đến hành vi ngoài mong đợi","intro":"Mô hình nhận diện ranh giới tin cậy, không phải hướng dẫn tạo hoặc triển khai mã độc.","nodes":[{"id":"source","slot":"a","label":"Gói phần mềm","caption":"Vẻ ngoài hữu ích","definition":"Tên gọi, giao diện hoặc lời giới thiệu tạo kỳ vọng về chức năng của phần mềm."},{"id":"user","slot":"b","label":"Người dùng","caption":"Quyết định chạy","definition":"Người dùng trao cơ hội thực thi khi chạy hoặc cho phép cài đặt."},{"id":"process","slot":"c","label":"Tiến trình","caption":"Quyền đang có","definition":"Mã thực thi nhận bối cảnh quyền và các hạn chế mà hệ điều hành áp dụng."},{"id":"behavior","slot":"f","label":"Hành vi phụ","caption":"Không đúng kỳ vọng","definition":"Hành vi có thể liên quan dữ liệu, cấu hình hoặc kết nối ngoài phạm vi chức năng đã công bố."},{"id":"observe","slot":"e","label":"Giám sát & chặn","caption":"Đối chiếu bằng chứng","definition":"Log, tiến trình, quyền, file và kết nối được đối chiếu để đánh giá dấu hiệu bất thường."}],"edges":[{"id":"a","fromId":"source","toId":"user","label":"1"},{"id":"b","fromId":"user","toId":"process","label":"2"},{"id":"c","fromId":"process","toId":"behavior","label":"3"},{"id":"d","fromId":"behavior","toId":"observe","label":"4"}],"steps":[{"title":"Vỏ bọc tạo niềm tin","body":"Trojan được nhận diện bởi việc giả dạng hoặc trình bày như phần mềm hữu ích trong khi có hành vi gây hại. Một chương trình có giao diện đẹp hoặc tên quen thuộc chưa được chứng minh an toàn chỉ vì nó giống phần mềm hợp lệ.","edges":["a"]},{"title":"Điểm chuyển ranh giới là thực thi","body":"Khi chạy mã, người dùng trao khả năng hoạt động trong phạm vi quyền hiện có. Việc tải một file và việc thực thi file là hai sự kiện khác nhau; cần phân biệt chúng khi phân tích một tình huống lây nhiễm.","edges":["b"]},{"title":"Hành vi phụ sử dụng quyền và tài nguyên","body":"Mã có thể làm việc không tương ứng với mục đích đã công bố. Không phải Trojan nào cũng điều khiển từ xa, tự khởi động hay cần quyền quản trị. Các khả năng đó tùy mẫu và môi trường, không phải điều kiện định nghĩa chung.","edges":["c"]},{"title":"Phòng thủ bằng quan sát nhiều nguồn","body":"Đối chiếu nguồn phát hành, chữ ký phần mềm, thay đổi hệ thống, tiến trình và kết nối. Một dấu hiệu riêng lẻ chưa đủ kết luận: ứng dụng hợp lệ cũng kết nối Internet. Điều quan trọng là hành vi có cần thiết và được phép trong bối cảnh đó hay không.","edges":["d"]}],"example":"Một ứng dụng học từ vựng yêu cầu quyền không liên quan và tạo kết nối không giải thích được cần được kiểm tra thêm. Không kết luận chỉ dựa trên tên ứng dụng hoặc một cổng đang mở.","limits":"Sơ đồ chỉ trình bày cơ chế tin cậy và quan sát phòng thủ; không giả định mọi Trojan đều có máy chủ điều khiển hoặc một chuỗi hành vi cố định.","mistakes":["Trojan không được định nghĩa bởi khả năng tự nhân bản.","Cổng mở hoặc một process lạ chưa đủ chứng minh có Trojan."],"check":{"question":"Trojan và virus khác ở tiêu chí cốt lõi nào?","answer":"Trojan nhấn mạnh sự ngụy trang/hành vi gây hại; virus nhấn mạnh lây bằng cách gắn vào đối tượng chủ."},"refs":[],"deep":[]},{"id":"keyboard-risk","chapter":"2a","section":"2a.3.2","title":"Dữ liệu nhập: kênh truyền an toàn chưa bảo vệ mọi điểm","intro":"Nhìn vòng đời dữ liệu từ thiết bị nhập đến ứng dụng và kết nối mạng để hiểu rủi ro keylogger ở mức khái niệm.","nodes":[{"id":"device","slot":"a","label":"Thiết bị nhập","caption":"Phím bấm","definition":"Bàn phím hoặc thiết bị nhập tạo sự kiện trước khi ứng dụng xử lý nội dung."},{"id":"os","slot":"b","label":"Hệ điều hành","caption":"Phân phối sự kiện","definition":"Hệ điều hành, driver và cơ chế nhập liệu chuyển thông tin đến nơi nhận phù hợp."},{"id":"app","slot":"c","label":"Ứng dụng","caption":"Bản rõ tại đầu cuối","definition":"Ứng dụng cần thấy dữ liệu người dùng nhập để xử lý tác vụ."},{"id":"tls","slot":"f","label":"Kênh TLS","caption":"Bảo vệ trên đường","definition":"Transport Layer Security bảo vệ dữ liệu trong kênh giữa hai đầu cuối sau thiết lập."},{"id":"dest","slot":"e","label":"Dịch vụ đích","caption":"Nhận nội dung","definition":"Máy chủ hợp lệ xử lý dữ liệu sau khi kết nối được giải mã ở đầu nhận."}],"edges":[{"id":"a","fromId":"device","toId":"os","label":"1"},{"id":"b","fromId":"os","toId":"app","label":"2"},{"id":"c","fromId":"app","toId":"tls","label":"3"},{"id":"d","fromId":"tls","toId":"dest","label":"4"}],"steps":[{"title":"Dữ liệu xuất hiện trước TLS","body":"Người dùng nhấn phím, hệ thống nhận các sự kiện nhập. TLS chưa tham gia ở đoạn này. Nếu có thiết bị ghi phím phần cứng trên đường tín hiệu, phần mềm quét file trên máy không nhất thiết quan sát được thiết bị đó.","edges":["a"]},{"title":"Rủi ro phụ thuộc điểm quan sát và quyền","body":"Phần mềm không được phép có thể tìm cách quan sát dữ liệu đầu cuối; mức khả thi phụ thuộc quyền, hệ điều hành và các cơ chế bảo vệ. Không được suy ra mọi ứng dụng đều đọc được bàn phím của mọi ứng dụng khác.","edges":["b"]},{"title":"Ứng dụng cần dữ liệu để thực hiện chức năng","body":"Trước khi gửi, ứng dụng thường phải xử lý bản rõ. Nếu chính ứng dụng hoặc máy đầu cuối bị xâm hại, việc mã hóa đường truyền không sửa được vấn đề đã xảy ra trước lúc dữ liệu vào kênh. Đây là khác biệt giữa bảo mật đầu cuối và bảo mật truyền tải.","edges":["c"]},{"title":"TLS vẫn có vai trò đúng phạm vi","body":"TLS chống nghe trộm hoặc sửa thông điệp trên đường truyền theo mô hình của giao thức. Bảo vệ bổ sung gồm kiểm soát cài đặt, quyền, cập nhật, kiểm tra thiết bị vật lý và quan sát đầu cuối. Cần chọn biện pháp theo điểm dữ liệu bị lộ.","edges":["d"]}],"example":"Nhập mật khẩu vào một ứng dụng trên máy không đáng tin cậy không trở nên an toàn chỉ vì trang có HTTPS. Ngược lại, điều này không có nghĩa HTTPS vô dụng: nó bảo vệ một ranh giới khác.","limits":"Hình không mô tả API ghi phím, cài đặt ẩn hoặc gửi dữ liệu thu thập. Nó chỉ phân biệt các điểm dữ liệu tồn tại trong hệ thống.","mistakes":["TLS không mã hóa tín hiệu từ bàn phím đến hệ điều hành.","Không phải mọi rủi ro ghi phím đều có cùng cơ chế hoặc cùng khả năng phát hiện."],"check":{"question":"Nếu mục tiêu là bảo vệ đoạn bàn phím → ứng dụng, chỉ bật HTTPS có đủ không?","answer":"Không. Cần bảo vệ thiết bị và đầu cuối, vì đoạn đó diễn ra trước phạm vi bảo vệ của TLS."},"refs":[],"deep":[]},{"id":"virus-worm","chapter":"2b","section":"2b.1.1","title":"Virus và worm: hai nhánh lan truyền khác nhau","intro":"Hai nhánh có chung hậu quả nhưng khác cách tạo bản sao và điều kiện kích hoạt.","nodes":[{"id":"host","slot":"a","label":"Đối tượng chủ","caption":"Nhánh virus","definition":"File hoặc đối tượng phù hợp mang phần mã virus; không đồng nhất với khái niệm máy chủ mạng."},{"id":"run","slot":"b","label":"Chủ được thực thi","caption":"Nhận điều khiển","definition":"Một cơ chế kích hoạt đưa điều khiển đến mã virus trong mô hình đang xét."},{"id":"copy","slot":"c","label":"Đối tượng chủ khác","caption":"Lây thêm","definition":"Virus tìm đối tượng có thể lây và gắn mã theo cơ chế của nó."},{"id":"worm","slot":"d","label":"Chương trình worm","caption":"Nhánh độc lập","definition":"Worm có khả năng tự lan sang hệ thống khác mà không cần gắn vào chương trình chủ theo định nghĩa virus."},{"id":"network","slot":"e","label":"Đường lan phù hợp","caption":"Mạng / dịch vụ","definition":"Việc lan truyền cần đường tiếp cận và điều kiện mà mẫu worm khai thác hoặc lợi dụng."},{"id":"machine","slot":"f","label":"Máy khác","caption":"Bản sao mới","definition":"Một bản sao được thực thi trên máy khác khi điều kiện lây nhiễm được đáp ứng."}],"edges":[{"id":"a","fromId":"host","toId":"run","label":"1"},{"id":"b","fromId":"run","toId":"copy","label":"2"},{"id":"c","fromId":"worm","toId":"network","label":"3"},{"id":"d","fromId":"network","toId":"machine","label":"4"}],"steps":[{"title":"Virus cần mối liên hệ với đối tượng chủ","body":"Virus có cơ chế gắn vào đối tượng chủ để được kích hoạt cùng một sự kiện thích hợp. Từ “host” ở đây nói về vật mang mã, không bắt buộc là server cung cấp dịch vụ. Chỉ có một file độc hại chưa đủ chứng minh nó là virus.","edges":["a"]},{"title":"Khi chạy, virus có thể lây sang đối tượng khác","body":"Sau khi nhận điều khiển, mã tìm đối tượng phù hợp rồi tạo sự lây nhiễm mới. Việc phá hoại và việc lây là hai chức năng khác nhau: có mẫu chưa biểu hiện phá hoại rõ nhưng vẫn có cơ chế lây. Không mô tả mọi mẫu là có cùng thứ tự nội bộ.","edges":["b"]},{"title":"Worm có chương trình lan truyền độc lập","body":"Worm không cần gắn vào file chủ theo cách định nghĩa virus. Tuy vậy, “tự lan” không có nghĩa vượt qua mọi mạng hoặc mọi máy: còn phụ thuộc dịch vụ, cấu hình, quyền và cơ chế mà mẫu đó sử dụng.","edges":["c"]},{"title":"Chọn điểm cắt theo đường lan","body":"Kiểm soát file và thực thi giúp với nhánh virus; vá lỗi, phân đoạn mạng và giới hạn dịch vụ có thể cắt nhánh worm. Thực tế một họ malware có thể kết hợp nhiều khả năng, nên phân loại là công cụ hiểu cơ chế chứ không thay điều tra hành vi.","edges":["d"]}],"example":"Một tài liệu mang mã lây khi người dùng mở khác với một chương trình lan qua dịch vụ mạng. Cả hai vẫn có thể làm gián đoạn máy hoặc ảnh hưởng dữ liệu.","limits":"Hai nhánh là mô hình phân biệt, không phải danh mục đầy đủ mọi cách lan hoặc mọi loại malware lai.","mistakes":["“Có hại” không tự đồng nghĩa “virus”.","Zombie mô tả trạng thái máy bị điều khiển, không phải cơ chế lây của virus."],"check":{"question":"Tại sao chặn chia sẻ file chưa chắc chặn mọi worm?","answer":"Vì đường lan có thể là dịch vụ/cơ chế khác; phải xác định điều kiện và đường tiếp cận cụ thể."},"refs":[],"deep":[]},{"id":"detection","chapter":"2b","section":"2b.4.2","title":"Ba cách phát hiện: nhận dạng, nghi vấn và so sánh","intro":"Ba nhánh trả lời ba câu hỏi khác nhau; phối hợp chúng tốt hơn đánh đồng chúng.","nodes":[{"id":"object","slot":"b","label":"File / hành vi","caption":"Đối tượng kiểm tra","definition":"Đầu vào có thể gồm nội dung file, thuộc tính hoặc hành vi được quan sát."},{"id":"signature","slot":"d","label":"Signature","caption":"Có khớp mẫu?","definition":"Mẫu nhận dạng mô tả đặc điểm đã biết để tìm dấu vết phù hợp."},{"id":"heuristic","slot":"e","label":"Heuristic","caption":"Có đáng ngờ?","definition":"Quy tắc hoặc mô hình suy luận từ đặc điểm, cấu trúc và hành vi."},{"id":"baseline","slot":"f","label":"Integrity check","caption":"Có thay đổi?","definition":"Giá trị kiểm tra hiện tại được so với baseline tin cậy."},{"id":"decision","slot":"h","label":"Đánh giá bối cảnh","caption":"Không kết luận máy móc","definition":"Kết quả được ghép với nguồn file, cập nhật, quyền, log và tác động thực tế."}],"edges":[{"id":"a","fromId":"object","toId":"signature","label":"1"},{"id":"b","fromId":"object","toId":"heuristic","label":"2"},{"id":"c","fromId":"object","toId":"baseline","label":"3"},{"id":"d","fromId":"signature","toId":"decision","label":"4"},{"id":"e","fromId":"heuristic","toId":"decision","label":"4"},{"id":"f","fromId":"baseline","toId":"decision","label":"4"}],"steps":[{"title":"Đối chiếu mẫu đã biết","body":"Signature phù hợp với đặc điểm đã được mô tả trong bộ nhận dạng. Nó có thể hoạt động nhanh và chính xác trong phạm vi mẫu; thiếu kết quả khớp không chứng minh an toàn, vì mẫu có thể mới hoặc đã biến đổi.","edges":["a"]},{"title":"Tìm dấu hiệu đáng nghi","body":"Heuristic dùng quy tắc/đặc trưng để nghi ngờ trường hợp chưa có mẫu chính xác. Phạm vi suy luận rộng hơn nhưng có thể đánh nhầm ứng dụng hợp lệ. Cần phân biệt một cảnh báo với một kết luận đã xác minh.","edges":["b"]},{"title":"Đối chiếu tính toàn vẹn","body":"Integrity Check Value (ICV) trong bối cảnh giám sát file được so với bản chuẩn. Khác giá trị cho biết file khác baseline theo phép kiểm, không tự chỉ ra nguyên nhân. Nếu baseline ban đầu đã nhiễm, so sánh với nó cũng không tạo được sự tin cậy.","edges":["c"]},{"title":"Ghép bằng chứng trước khi xử lý","body":"Một bản cập nhật hợp lệ có thể làm hash thay đổi. Ngược lại, file giữ nguyên kích thước vẫn có thể thay nội dung. Quyết định cần bối cảnh nguồn phát hành, sự kiện cập nhật và các dấu hiệu khác; không chỉ nhìn một con số.","edges":["d","e","f"]}],"example":"Sau khi cập nhật phần mềm chính thức, hash khác baseline cũ là điều có thể dự đoán. Hãy xác minh nguồn và bản cập nhật, rồi cập nhật baseline theo quy trình, thay vì mặc định xóa file.","limits":"Mô hình so sánh nguyên tắc, không mô phỏng độ chính xác của một antivirus hoặc mọi kỹ thuật phân tích.","mistakes":["ICV thay đổi không đồng nghĩa chắc chắn có virus.","Heuristic không phải phép chứng minh tuyệt đối."],"check":{"question":"Hash không đổi so với một baseline bị nhiễm có chứng minh file sạch không?","answer":"Không. Tính tin cậy của baseline là điều kiện nền tảng của phép so sánh."},"refs":[],"deep":[]},{"id":"symmetric","chapter":"3","section":"3.4.1","title":"Mã hóa đối xứng: cùng bí mật, hai chiều xử lý","intro":"Phân biệt bản rõ, thuật toán, khóa và bản mã; khóa không đi kèm công khai với bản mã.","nodes":[{"id":"m","slot":"a","label":"Bản rõ m","caption":"Dữ liệu cần bảo vệ","definition":"Thông điệp trước mã hóa; phải được biểu diễn thành chuỗi bit/byte phù hợp."},{"id":"enc","slot":"b","label":"Mã hóa E","caption":"Dùng khóa K","definition":"Phép mã hóa phụ thuộc thuật toán, khóa và các tham số như nonce/IV theo chế độ."},{"id":"cipher","slot":"c","label":"Bản mã c","caption":"Đi qua kênh","definition":"Dữ liệu được biến đổi để người không có khóa khó suy ra bản rõ trong mô hình an toàn."},{"id":"dec","slot":"f","label":"Giải mã D","caption":"Dùng khóa tương ứng","definition":"Đầu nhận có bí mật đối xứng phù hợp để khôi phục thông điệp."},{"id":"out","slot":"e","label":"Bản rõ m","caption":"Kết quả khôi phục","definition":"Thông điệp sau giải mã còn phải được xử lý theo cơ chế kiểm tra toàn vẹn/xác thực được dùng."}],"edges":[{"id":"a","fromId":"m","toId":"enc","label":"1 · m"},{"id":"b","fromId":"enc","toId":"cipher","label":"2 · c"},{"id":"c","fromId":"cipher","toId":"dec","label":"3 · c"},{"id":"d","fromId":"dec","toId":"out","label":"4 · m"}],"steps":[{"title":"Hai bên phải có khóa theo cách an toàn","body":"K là tham số bí mật, khác với tên thuật toán. Biết thuật toán không được xem là biết khóa. Bài toán phân phối/thiết lập khóa tồn tại trước hoặc trong giao thức; chỉ gửi khóa cùng bản mã qua cùng kênh không bảo vệ thì mất ý nghĩa bí mật.","edges":["a"]},{"title":"Mã hóa phụ thuộc cả chế độ sử dụng","body":"Viết gọn c=E(K,m) giúp hiểu nguyên tắc. Một phép triển khai còn cần encoding, chia khối và tham số của mode. IV/nonce không nhất thiết bí mật nhưng phải đáp ứng điều kiện của mode; tái sử dụng sai có thể làm lộ quan hệ giữa các thông điệp.","edges":["b"]},{"title":"Người nhận dùng đúng khóa và tham số","body":"Đầu nhận lấy c và các tham số cần thiết, áp dụng D để phục hồi m. Bản mã có thể bị thay, gửi thiếu hoặc phát lại; việc nhìn nó “không đọc được” chưa chứng minh nó chưa bị can thiệp.","edges":["c"]},{"title":"Khôi phục không đồng nghĩa đã xác thực","body":"Mã hóa thuần túy không tự bảo đảm toàn vẹn. Một thiết kế có xác thực dùng tag và từ chối dữ liệu không hợp lệ trước khi sử dụng kết quả theo quy tắc của nó. Chống replay cần cơ chế tính mới bổ sung phù hợp.","edges":["d"]}],"example":"Alice và Bob đã có K. Alice mã hóa tài liệu, Bob giải mã bằng K tương ứng. Nếu người khác lấy được K, bảo mật của các dữ liệu chịu ảnh hưởng của khóa đó có thể mất dù thuật toán không đổi.","limits":"Hình bỏ qua mode cụ thể và quản lý khóa chi tiết; không phải mọi hệ đối xứng đều có cấu trúc nội bộ giống nhau.","mistakes":["Độ dài khối khác độ dài khóa.","Bí mật thuật toán không thay được bí mật khóa."],"check":{"question":"Tại sao AES mạnh nhưng dùng nonce sai vẫn có thể nguy hiểm?","answer":"Độ an toàn phụ thuộc cả thuật toán lẫn cách sử dụng mode và tham số; không chỉ phụ thuộc tên AES."},"refs":[],"deep":[]},{"id":"feistel","chapter":"3","section":"3.4.2","title":"Một vòng Feistel của DES: đổi chỗ và XOR","intro":"Theo dõi đúng hai nửa dữ liệu thay vì học thuộc tên các phép biến đổi.","nodes":[{"id":"left","slot":"a","label":"Lᵢ₋₁","caption":"Nửa trái · 32 bit","definition":"Nửa trái của khối 64 bit trước vòng đang xét."},{"id":"right","slot":"b","label":"Rᵢ₋₁","caption":"Nửa phải · 32 bit","definition":"Nửa phải đồng thời đi vào F và trở thành nửa trái vòng sau."},{"id":"fun","slot":"e","label":"F(R, Kᵢ)","caption":"Khóa con 48 bit","definition":"Hàm vòng DES: mở rộng 32→48 bit, XOR khóa con, S-box 48→32 bit rồi hoán vị P."},{"id":"nextleft","slot":"c","label":"Lᵢ = Rᵢ₋₁","caption":"Chuyển sang trái","definition":"Một nhánh được chuyển nguyên vẹn sang nửa trái vòng kế tiếp."},{"id":"xor","slot":"d","label":"Rᵢ = Lᵢ₋₁ ⊕ F","caption":"Nửa phải mới","definition":"XOR hai giá trị 32 bit tạo nửa phải sau vòng; ⊕ là XOR theo từng bit."}],"edges":[{"id":"a","fromId":"right","toId":"nextleft","label":"1"},{"id":"b","fromId":"right","toId":"fun","label":"2"},{"id":"c","fromId":"left","toId":"xor","label":"3 · L"},{"id":"d","fromId":"fun","toId":"xor","label":"3 · XOR"}],"steps":[{"title":"Tách và đặt tên theo vòng","body":"DES xử lý khối 64 bit. Ở vòng i, đầu vào là hai nửa Lᵢ₋₁ và Rᵢ₋₁, mỗi nửa 32 bit. Chỉ số là số vòng, không phải số bit. Tách tên rõ giúp tránh nhầm bên nào đi vào F.","edges":["a"]},{"title":"Hàm F trộn nửa phải với khóa vòng","body":"DES mở rộng R từ 32 lên 48 bit, XOR với Kᵢ 48 bit. Tám S-box nhận tổng 48 bit và trả tổng 32 bit; sau đó P hoán vị các bit. S-box tạo phi tuyến, còn hoán vị giúp phân tán ảnh hưởng qua các vòng.","edges":["b"]},{"title":"Tạo hai nửa mới","body":"Lᵢ=Rᵢ₋₁; Rᵢ=Lᵢ₋₁⊕F(Rᵢ₋₁,Kᵢ). Không phải cả hai nửa đều độc lập chạy qua F. Nửa phải cũ có hai vai trò: chuyển sang trái và cung cấp đầu vào cho F.","edges":["c","d"]},{"title":"Vì sao đảo được dù F không cần đảo được?","body":"Khi biết Lᵢ,Rᵢ, suy ra Rᵢ₋₁=Lᵢ và Lᵢ₋₁=Rᵢ⊕F(Lᵢ,Kᵢ). Vì x⊕y⊕y=x, có thể khôi phục nửa cũ. Trong mạng Feistel, dùng khóa vòng theo thứ tự ngược giúp giải mã; vẫn cần đúng các hoán vị/đổi chỗ của toàn bộ DES.","edges":["a","b","c","d"]}],"example":"Ví dụ XOR đơn giản: 1010⊕0110=1100; 1100⊕0110=1010. Đây chỉ minh họa tính tự đảo của XOR, không thay F hoặc mô phỏng đầy đủ một vòng DES.","limits":"Hình là một vòng, bỏ qua IP, FP, lịch khóa và cách ghép cuối. DES có 16 vòng, khóa hiệu dụng 56 bit; đây là nội dung lịch sử, không phải khuyến nghị dùng DES mới.","mistakes":["S-box làm thay đổi giá trị, không chỉ đổi vị trí.","F không cần khả nghịch để mạng Feistel khả nghịch."],"check":{"question":"Biết Lᵢ,Rᵢ và Kᵢ, tại sao không cần tính F nghịch đảo?","answer":"Vì tính lại F với nửa phải cũ đã suy ra, sau đó dùng XOR để lấy lại nửa trái cũ."},"refs":[],"deep":[{"title":"Bên trong F: độ dài thay đổi ở đâu?","body":"E mở rộng R từ 32 lên 48 bit bằng cách chọn/lặp một số bit theo bảng, không tạo thêm thông tin bí mật. XOR với Kᵢ giữ độ dài 48 bit. Chia thành 8 nhóm, mỗi nhóm 6 bit đi qua một S-box để nhận 4 bit: 8×4=32 bit. P chỉ đổi vị trí 32 bit đó. Vì thế F nhận nửa khối 32 bit nhưng khóa con có 48 bit."},{"title":"Đọc một đầu vào S-box","body":"Với nhóm 6 bit b₁b₂b₃b₄b₅b₆, lấy b₁b₆ làm chỉ số hàng 0..3 và b₂b₃b₄b₅ làm chỉ số cột 0..15. Tra đúng S-box tương ứng với vị trí nhóm, rồi biểu diễn kết quả thành 4 bit. Ví dụ 011011 chọn hàng 01₂=1, cột 1101₂=13. Không dùng cả sáu bit làm chỉ số cột, cũng không dùng cùng một bảng S-box cho cả tám nhóm."}]},{"id":"aes","chapter":"3","section":"3.4.3","title":"AES-128: khối dữ liệu đi qua các vòng như thế nào?","intro":"Đi từ state 4×4 byte đến bốn phép biến đổi; phân biệt một vòng với toàn bộ phép mã hóa.","nodes":[{"id":"state","slot":"a","label":"State 4 × 4 byte","caption":"Khối 128 bit","definition":"16 byte được sắp thành state theo quy ước AES; không phải bốn khối độc lập."},{"id":"key","slot":"b","label":"AddRoundKey","caption":"XOR khóa vòng","definition":"XOR state với một khóa vòng 128 bit sinh từ lịch khóa."},{"id":"sub","slot":"c","label":"SubBytes","caption":"Thay từng byte","definition":"Áp dụng cùng S-box khả nghịch lên mỗi byte để tạo phi tuyến."},{"id":"shift","slot":"f","label":"ShiftRows","caption":"Dịch theo hàng","definition":"Các hàng dịch vòng khác độ lệch, làm byte chuyển sang cột khác."},{"id":"mix","slot":"e","label":"MixColumns","caption":"Trộn từng cột","definition":"Biến đổi tuyến tính khả nghịch trên GF(2⁸) để mỗi byte đầu ra phụ thuộc nhiều byte trong cột."},{"id":"end","slot":"d","label":"AddRoundKey","caption":"Kết thúc vòng","definition":"Khóa vòng tiếp theo được XOR vào state đã biến đổi."}],"edges":[{"id":"a","fromId":"state","toId":"key","label":"0 · ban đầu"},{"id":"b","fromId":"key","toId":"sub","label":"1"},{"id":"c","fromId":"sub","toId":"shift","label":"2"},{"id":"d","fromId":"shift","toId":"mix","label":"3"},{"id":"e","fromId":"mix","toId":"end","label":"4"}],"steps":[{"title":"Nạp khối và cộng khóa ban đầu","body":"AES-128 nhận khối 128 bit, xếp thành state 16 byte và thực hiện AddRoundKey đầu tiên. Khóa vòng là 128 bit; một word 32 bit chỉ là thành phần của khóa vòng. Dữ liệu dài hơn cần chế độ mã hóa phù hợp.","edges":["a"]},{"title":"SubBytes thay giá trị từng byte","body":"Mỗi byte đi qua S-box. Đây không phải đổi thứ tự byte: giá trị byte thay theo bảng/ánh xạ xác định và khả nghịch. Tính phi tuyến giúp phá vỡ các quan hệ tuyến tính đơn giản giữa đầu vào, khóa và đầu ra.","edges":["b"]},{"title":"ShiftRows chuyển vị trí","body":"Hàng 0 giữ nguyên; các hàng 1,2,3 dịch vòng lần lượt 1,2,3 vị trí trong chiều mã hóa. Nó chưa trộn số học các byte, nhưng đưa các byte của một cột sang các cột khác, chuẩn bị cho khuếch tán qua MixColumns.","edges":["c"]},{"title":"MixColumns lan ảnh hưởng trong cột","body":"Mỗi cột được nhân với ma trận cố định trong trường hữu hạn GF(2⁸). Phép cộng là XOR, phép nhân không phải nhân số nguyên thông thường. Sau nhiều vòng, kết hợp ShiftRows và MixColumns giúp thay đổi một byte ảnh hưởng rộng hơn trong state.","edges":["d"]},{"title":"Cộng khóa vòng và lặp có ngoại lệ","body":"Một vòng thường kết thúc bằng AddRoundKey. AES-128 có 10 vòng sau phép cộng khóa ban đầu; vòng cuối bỏ MixColumns. Vì vậy có 11 khóa vòng. AES-192/256 vẫn có khối 128 bit nhưng có 12/14 vòng và số khóa vòng khác.","edges":["e"]}],"example":"Hãy đánh dấu một byte bằng màu tưởng tượng: SubBytes đổi giá trị; ShiftRows đổi vị trí; MixColumns lan ảnh hưởng sang các byte cùng cột; AddRoundKey đưa ảnh hưởng của khóa vòng vào. Đây là cách kể cơ chế, không phải tính ciphertext cụ thể.","limits":"Hình tách các phép để dễ nhìn; hai hộp AddRoundKey là hai thời điểm khác nhau. Không lặp phép cộng khóa ban đầu trước mọi vòng. Vòng cuối không có MixColumns.","mistakes":["128 bit là độ dài khối của mọi biến thể AES.","11 khóa vòng chỉ đúng AES-128.","MixColumns dùng số học trường hữu hạn."],"check":{"question":"Tại sao nói “AES có 10 vòng” mà không nêu biến thể là thiếu chính xác?","answer":"Vì chỉ AES-128 có 10 vòng; AES-192 và AES-256 lần lượt có 12 và 14 vòng."},"refs":["https://csrc.nist.gov/pubs/fips/197/final"],"deep":[{"title":"ShiftRows: thấy rõ từng hàng","body":"Giả sử bốn hàng chứa [a b c d], [e f g h], [i j k l], [m n o p]. Sau ShiftRows của chiều mã hóa, chúng thành [a b c d], [f g h e], [k l i j], [p m n o]. Chữ chỉ đại diện byte, không phải phép cộng ký tự. Một byte chuyển vị trí nhưng chưa bị thay giá trị ở chính phép này."},{"title":"MixColumns: công thức một cột","body":"Với cột (a₀,a₁,a₂,a₃), byte đầu ra đầu tiên là b₀=(02·a₀)⊕(03·a₁)⊕a₂⊕a₃. Ba hàng hệ số tiếp theo là [01 02 03 01], [01 01 02 03], [03 01 01 02]. Các hệ số là byte hex; tích nằm trong GF(2⁸), phép cộng là XOR. Giảm đa thức theo x⁸+x⁴+x³+x+1, không lấy modulo số nguyên 256. Nhân 03 với a có thể viết (02·a)⊕a. Vòng cuối bỏ phép này."},{"title":"Khóa vòng đến từ đâu?","body":"Ở AES-128, khóa gốc gồm 4 word, mỗi word 4 byte. Key expansion tạo 44 word, ghép từng 4 word thành 11 khóa vòng 16 byte. Tại bước đặc biệt của lịch khóa có RotWord, SubWord và hằng số Rcon, kết hợp XOR với word trước phù hợp. Khóa vòng được dẫn xuất từ khóa gốc, không từ ciphertext. AddRoundKey XOR từng byte tương ứng của state và khóa vòng; kích thước hai đầu vào phải khớp."}]},{"id":"rsa","chapter":"4","section":"4.4.1","title":"RSA: tạo khóa, mã hóa và giải mã một số nhỏ","intro":"Đi một ví dụ tính tay trọn vẹn để hiểu vai trò từng đại lượng; không dùng tham số nhỏ cho bảo mật thực tế.","nodes":[{"id":"primes","slot":"a","label":"p = 5, q = 11","caption":"Hai số nguyên tố","definition":"Hai số nguyên tố khác nhau được chọn để minh họa tạo khóa."},{"id":"params","slot":"b","label":"n = 55, φ = 40","caption":"Môđun & Euler phi","definition":"n=pq; với p,q nguyên tố khác nhau, φ(n)=(p−1)(q−1)."},{"id":"keys","slot":"c","label":"e = 3, d = 27","caption":"ed ≡ 1 (mod 40)","definition":"Public key=(e,n); private exponent d và thông tin khóa riêng phải giữ bí mật."},{"id":"encrypt","slot":"f","label":"m = 7 → c = 13","caption":"c = mᵉ mod n","definition":"Bản rõ được mã hóa thành số nguyên trong khoảng 0≤m<n theo mô hình RSA trần."},{"id":"decrypt","slot":"e","label":"c = 13 → m = 7","caption":"m = cᵈ mod n","definition":"Giải mã dùng d tương ứng để phục hồi đại diện số của thông điệp."}],"edges":[{"id":"a","fromId":"primes","toId":"params","label":"1"},{"id":"b","fromId":"params","toId":"keys","label":"2"},{"id":"c","fromId":"keys","toId":"encrypt","label":"3"},{"id":"d","fromId":"encrypt","toId":"decrypt","label":"4"}],"steps":[{"title":"Tạo môđun và giá trị phục vụ tìm khóa","body":"Chọn p=5,q=11 nên n=55, φ(n)=4×10=40. Các số này không có đơn vị vật lý. n được công khai; việc giữ bí mật p,q quan trọng vì phân tích được n sẽ giúp xây dựng lại thông tin giải mã trong mô hình này.","edges":["a"]},{"title":"Chọn e và tìm d bằng nghịch đảo môđun","body":"e=3 nguyên tố cùng nhau với 40. Chọn d=27 vì 3×27=81=2×40+1. d không bằng 1/e theo số thực; nó là nghịch đảo nhân trong phép tính modulo. Ví dụ dùng điều kiện theo φ(n) như trong bài nhập môn.","edges":["b"]},{"title":"Mã hóa với public key của người nhận","body":"m=7 nằm trong 0..54. c=7³ mod55=343 mod55=13. Bất kỳ ai biết public key đều có thể mã hóa một đại diện số cho chủ khóa; điều đó không tự chứng minh danh tính người gửi.","edges":["c"]},{"title":"Giải mã bằng d và kiểm tra phép tính","body":"13² mod55=4; 13⁴ mod55=16; 13⁸ mod55=36; 13¹⁶ mod55=31. Vì 27=16+8+2+1, lấy 31×36×4×13 mod55 được 7. Bình phương–nhân giúp không cần tạo số nguyên khổng lồ trước khi lấy dư.","edges":["d"]}],"example":"Chuỗi số đầy đủ: (5,11) → (55,40) → (e=3,d=27) → 7 → 13 → 7. Điểm cần tự giải thích là vì sao public key cho phép mã hóa nhưng không được kỳ vọng cho phép suy ra d hiệu quả với tham số đủ mạnh.","limits":"RSA trần trong hình là bài toán học thuật. Hệ thống thực dùng encoding/padding và giao thức chuẩn, chẳng hạn RSA-OAEP cho mã hóa; không tự ghép RSA trần để bảo vệ dữ liệu. Chữ ký RSA cũng không đơn giản là “mã hóa ngược”.","mistakes":["d là nghịch đảo modulo, không là nghịch đảo số thực.","Chỉ bí mật khóa riêng; không cần bí mật public key.","Ví dụ nhỏ không có độ an toàn thực tế."],"check":{"question":"Nếu e=4 trong ví dụ φ(n)=40 thì có tìm d theo yêu cầu không?","answer":"Không. gcd(4,40)=4≠1 nên không có nghịch đảo nhân modulo 40."},"refs":[],"deep":[{"title":"Vì sao cần biểu diễn thông điệp và padding?","body":"Công thức c=mᵉ mod n thao tác trên một số nguyên trong khoảng quy định, không trực tiếp trên một câu tiếng Việt tùy độ dài. Hệ thực mã hóa byte theo một scheme chuẩn trước khi áp phép RSA. RSA trần có tính xác định: cùng m và public key cho cùng c, nên tập đầu vào nhỏ có thể bị đối chiếu ứng viên. Không khắc phục bằng việc giữ bí mật e; e vốn là tham số công khai."}]},{"id":"dh","chapter":"4","section":"4.3","title":"Diffie–Hellman: không gửi bí mật vẫn cùng ra một khóa","intro":"Theo dõi hai phép tính gặp nhau ở g^(ab) mod p và điều kiện xác thực còn thiếu.","nodes":[{"id":"public","slot":"b","label":"p = 23, g = 5","caption":"Tham số công khai","definition":"p,g được công khai trong ví dụ nhóm nhỏ; hệ thực cần nhóm/tham số được lựa chọn phù hợp."},{"id":"alice","slot":"d","label":"Alice: a = 6","caption":"A = 5⁶ mod23 = 8","definition":"a là bí mật cục bộ của Alice; A là giá trị công khai được trao đổi."},{"id":"bob","slot":"f","label":"Bob: b = 15","caption":"B = 5¹⁵ mod23 = 19","definition":"b là bí mật cục bộ của Bob; B là giá trị công khai được trao đổi."},{"id":"ka","slot":"g","label":"Alice tính Bᵃ","caption":"19⁶ mod23 = 2","definition":"Alice dùng giá trị công khai Bob gửi và bí mật riêng a."},{"id":"kb","slot":"i","label":"Bob tính Aᵇ","caption":"8¹⁵ mod23 = 2","definition":"Bob dùng giá trị công khai Alice gửi và bí mật riêng b."}],"edges":[{"id":"a","fromId":"public","toId":"alice","label":"1"},{"id":"b","fromId":"public","toId":"bob","label":"1"},{"id":"c","fromId":"alice","toId":"bob","label":"2 · A=8"},{"id":"d","fromId":"bob","toId":"alice","label":"2 · B=19"},{"id":"e","fromId":"alice","toId":"ka","label":"3"},{"id":"f","fromId":"bob","toId":"kb","label":"3"}],"steps":[{"title":"Hai bên thống nhất nhóm công khai","body":"Alice và Bob biết p=23,g=5. Không coi những giá trị này là mật khẩu. Đối phương nghe được p,g,A,B vẫn phải giải bài toán khó tương ứng để suy ra bí mật trong một nhóm đủ mạnh; ví dụ nhỏ ở đây chỉ phục vụ tính tay.","edges":["a","b"]},{"title":"Chỉ trao đổi kết quả lũy thừa","body":"Alice giữ a=6, gửi A=8; Bob giữ b=15, gửi B=19. a và b không được gửi cho nhau. Cần phân biệt chữ hoa giá trị công khai với chữ thường bí mật để không nhầm thứ phải bảo vệ.","edges":["c","d"]},{"title":"Hai đường tính đến cùng bí mật","body":"Alice tính Bᵃ=(gᵇ)ᵃ; Bob tính Aᵇ=(gᵃ)ᵇ. Cả hai bằng g^(ab) trong nhóm. Ở ví dụ này đều bằng 2. Hệ thực đưa bí mật chia sẻ qua hàm dẫn xuất khóa, không xem ngay số nhỏ thô là khóa AES hợp lệ.","edges":["e","f"]},{"title":"Cùng ra số chưa chứng minh đúng người","body":"DH thuần túy không xác thực người gửi A,B. Nếu giá trị công khai bị thay, hai bên có thể thiết lập bí mật với một trung gian thay vì với nhau. Giao thức cần ràng buộc trao đổi với danh tính bằng chữ ký/chứng chỉ hoặc bí mật có trước phù hợp.","edges":["c","d"]}],"example":"Tự bấm máy: 5⁶ mod23=8, 5¹⁵ mod23=19, 19⁶ mod23=2 và 8¹⁵ mod23=2. Không có bước nào phải truyền a=6 hoặc b=15.","limits":"Tham số rất nhỏ, không dùng triển khai. Hình lược bỏ kiểm tra giá trị công khai, lựa chọn nhóm, KDF và cơ chế xác thực của giao thức bao ngoài.","mistakes":["Trao đổi khóa không đồng nghĩa mã hóa thông điệp.","Không gửi khóa không có nghĩa tự chống MITM."],"check":{"question":"Người nghe trộm biết A và B có phải đã biết a và b không?","answer":"Không. Đảo từ giá trị công khai về số mũ là bài toán khác; với nhóm đủ mạnh được giả định khó, nhưng nhóm nhỏ minh họa này không an toàn."},"refs":[],"deep":[{"title":"Hai bên cùng số 2 nhưng không gửi số 2","body":"Alice nhận B=19 rồi tính B⁶ mod23; Bob nhận A=8 rồi tính A¹⁵ mod23. Hai kết quả trùng do phép lũy thừa trong cùng nhóm, không do so sánh bí mật qua mạng. Trong một giao thức thực, bí mật chia sẻ cùng transcript/ngữ cảnh có thể được đưa vào KDF để tạo các khóa riêng biệt cho từng mục đích. Không dùng trực tiếp cách viết số thập phân 2 làm mật khẩu hay khóa AES."},{"title":"Tại sao xác thực phải ràng buộc đúng cuộc trao đổi?","body":"Nếu chỉ kiểm danh tính ở một thông điệp không gắn với các giá trị A,B và ngữ cảnh phiên, người nhận có thể xác thực một thứ nhưng dùng khóa của cuộc trao đổi khác. Giao thức cần ràng buộc bằng chứng danh tính với thông số và transcript phù hợp. Vì thế không tự ghép “DH rồi thêm một chữ ký bất kỳ” mà coi như đã có một giao thức an toàn."}]},{"id":"hash","chapter":"5","section":"5.3.1","title":"Hàm băm: kiểm tra dấu vết, không phải giải mã","intro":"Nhìn rõ phép so sánh hai digest và điều kiện nguồn digest phải đáng tin.","nodes":[{"id":"original","slot":"a","label":"File gốc m","caption":"Độ dài bất kỳ","definition":"Đầu vào là chuỗi byte; thay encoding cũng có thể làm byte thay đổi."},{"id":"hash1","slot":"b","label":"H(m)","caption":"Digest n bit","definition":"Hàm băm mật mã ánh xạ đầu vào thành đầu ra cố định với thuật toán đã chọn."},{"id":"trusted","slot":"c","label":"Digest chuẩn","caption":"Kênh tin cậy","definition":"Giá trị đối chiếu cần được xác thực hoặc nhận từ nguồn đáng tin."},{"id":"received","slot":"d","label":"File nhận m′","caption":"Có thể đã khác","definition":"File cần được kiểm tra sau tải hoặc sau lưu trữ."},{"id":"hash2","slot":"e","label":"H(m′)","caption":"Cùng thuật toán","definition":"Tính lại từ chính byte nhận, không so tên file hoặc chỉ so kích thước."},{"id":"compare","slot":"f","label":"So sánh digest","caption":"Bằng / khác","definition":"Kết quả cần diễn giải theo tính chất và độ an toàn của hàm băm."}],"edges":[{"id":"a","fromId":"original","toId":"hash1","label":"1"},{"id":"b","fromId":"hash1","toId":"trusted","label":"2"},{"id":"c","fromId":"received","toId":"hash2","label":"3"},{"id":"d","fromId":"hash2","toId":"compare","label":"4"},{"id":"e","fromId":"trusted","toId":"compare","label":"4"}],"steps":[{"title":"Rút thông điệp thành digest","body":"Hash không có khóa giải mã để lấy lại toàn bộ file. Do tập đầu vào lớn hơn tập đầu ra cố định, va chạm tồn tại về toán học. Mục tiêu an toàn là khiến việc tìm những va chạm/tiền ảnh phù hợp trở nên khó, không phải tuyên bố không thể có.","edges":["a"]},{"title":"Bảo vệ nguồn của dấu vết chuẩn","body":"Nếu đối phương thay được cả file lẫn digest đăng cạnh file, họ có thể tính digest mới cho file đã sửa. Vì vậy “có hash trên trang” khác với “có digest chuẩn đã được xác thực”.","edges":["b"]},{"title":"Tính lại trên dữ liệu thực nhận","body":"Dùng cùng thuật toán và cùng cách biểu diễn byte. Việc đổi xuống dòng hoặc encoding có thể làm hash khác dù nội dung nhìn tương tự. Hash kiểm tra byte, không hiểu ý nghĩa tài liệu.","edges":["c"]},{"title":"Diễn giải kết quả có điều kiện","body":"Digest khác chứng minh hai chuỗi byte khác dưới phép tính đúng. Digest bằng không phải chứng minh tuyệt đối hai đầu vào giống nhau, vì va chạm có thể tồn tại; mức tin cậy phụ thuộc hàm băm và mô hình đối phương. Băm trần không tự xác thực người gửi.","edges":["d","e"]}],"example":"Tải một bản cài và so SHA-256 với digest lấy qua nguồn đã xác thực giúp kiểm tra file. Nếu chỉ lấy file và digest từ cùng một nguồn đã bị thay, phép so sánh có thể vẫn đạt.","limits":"Hình mô tả băm mật mã, không đồng nhất với XOR-hash minh họa hoặc checksum chống lỗi ngẫu nhiên.","mistakes":["Hash không phải mã hóa một chiều có thể giải bằng khóa.","Digest bằng không tự chứng minh nguồn gốc."],"check":{"question":"Vì sao đặt digest cạnh file chưa đủ chống người sửa được cả hai?","answer":"Vì hàm băm công khai: đối phương cũng tính được digest của file thay thế."},"refs":[],"deep":[]},{"id":"mac","chapter":"5","section":"5.2.1","title":"MAC/HMAC: người biết khóa tạo và kiểm tag","intro":"Khác biệt quyết định với hash trần là bí mật chia sẻ K.","nodes":[{"id":"send","slot":"a","label":"Alice: m, K","caption":"Tạo thông điệp","definition":"Alice và Bob đã có cùng khóa bí mật K."},{"id":"tag","slot":"b","label":"T = MAC(K,m)","caption":"Tag xác thực","definition":"Với HMAC, cấu trúc hash có khóa tạo tag; không phải thêm checksum vào hash."},{"id":"channel","slot":"c","label":"Gửi m và T","caption":"K không gửi kèm","definition":"Thông điệp có thể vẫn là bản rõ nếu không có lớp mã hóa riêng."},{"id":"verify","slot":"f","label":"Bob tính T′","caption":"T′ = MAC(K,m nhận)","definition":"Bob dùng cùng khóa và thuật toán để tính lại tag trên dữ liệu thực nhận."},{"id":"decision","slot":"e","label":"So sánh T và T′","caption":"Chấp nhận / loại","definition":"Chỉ sử dụng nội dung khi thỏa toàn bộ kiểm tra giao thức, gồm tính mới nếu cần."}],"edges":[{"id":"a","fromId":"send","toId":"tag","label":"1"},{"id":"b","fromId":"tag","toId":"channel","label":"2"},{"id":"c","fromId":"channel","toId":"verify","label":"3"},{"id":"d","fromId":"verify","toId":"decision","label":"4"}],"steps":[{"title":"Khóa tạo sự khác biệt với hash công khai","body":"Người không có K không được kỳ vọng tạo tag hợp lệ cho thông điệp giả mạo trong điều kiện an toàn. Tuy nhiên cả Alice lẫn Bob đều biết K, nên cả hai đều có khả năng tạo tag. Điều này quan trọng khi hỏi về chống chối bỏ.","edges":["a"]},{"title":"Tag đi cùng thông điệp, không che nội dung","body":"Gửi m,T là đủ để đầu nhận kiểm MAC; K phải được giữ bí mật qua cơ chế khác. Ai quan sát kênh vẫn có thể đọc m nếu nó không được mã hóa. Tính xác thực/toàn vẹn và tính bí mật là những mục tiêu khác nhau.","edges":["b"]},{"title":"Tính lại trên thông điệp nhận","body":"Nếu dữ liệu đổi thành m′, Bob tính MAC(K,m′), không tính lại trên bản m cũ tưởng rằng đã nhận. Một thay đổi thông thường sẽ làm tag kiểm tra không khớp. Tag đủ dài và khóa phù hợp hạn chế khả năng đoán giả mạo; không nói xác suất bằng 0.","edges":["c"]},{"title":"MAC đúng còn cần bối cảnh và tính mới","body":"Thông điệp cũ có tag đúng có thể bị phát lại. Giao thức phải xác thực cả trường liên quan như số thứ tự, định danh phiên, ngữ cảnh và kiểm tra chúng. MAC không chứng minh cho bên thứ ba rằng chỉ riêng Alice có thể tạo thông điệp đó.","edges":["d"]}],"example":"Alice gửi “số tiền=100” và T. Nếu dữ liệu bị đổi thành “số tiền=900”, Bob phải tính tag từ chuỗi mới rồi so với T; chỉ đổi nội dung mà không biết K không đủ để tạo một thông điệp hợp lệ như người gửi.","limits":"Đây là mô hình MAC chung. HMAC có cấu trúc lồng hash với ipad/opad, không tự đặt công thức H(K||m) thay HMAC. Hình không mô phỏng tính toán mật mã thực.","mistakes":["MAC không tự mã hóa m.","Khóa chung không tạo bằng chứng chống chối bỏ độc lập."],"check":{"question":"Vì sao Bob không dùng tag để chứng minh chỉ Alice đã tạo m cho một người thứ ba?","answer":"Vì chính Bob cũng biết K và có thể tạo một tag như vậy."},"refs":["https://www.rfc-editor.org/info/rfc2104/"],"deep":[{"title":"Bên trong HMAC: hash lồng có khóa","body":"Dạng cấu trúc: HMAC(K,m)=H((K′⊕opad) || H((K′⊕ipad) || m)). H là hàm băm; || là nối byte. Chuẩn hóa K thành K′ dài bằng kích thước block của H: nếu khóa quá dài thì băm trước, sau đó đệm 0 cho đủ block. ipad là byte 0x36 lặp lại, opad là 0x5c lặp lại. Hash trong xử lý lớp khóa trong và m; hash ngoài xử lý lớp khóa ngoài và digest trong. Đây không phải checksum, không phải đơn giản H(K||m)."},{"title":"Vì sao có tag đúng mà vẫn cần số thứ tự?","body":"Người nhận dùng HMAC kiểm nội dung và ngữ cảnh được đưa vào phép tính. Nếu số thứ tự chỉ gửi ở ngoài nhưng không được xác thực, dữ liệu bảo vệ có thể không ràng buộc đúng trạng thái. Nếu một thông điệp hợp lệ cũ được dùng lại, tag vẫn có thể đúng; máy nhận cần kiểm thêm số thứ tự/nonce và trạng thái phiên để tránh thực hiện lại yêu cầu."}]},{"id":"signature","chapter":"5","section":"5.4","title":"Chữ ký số: ký bằng khóa riêng, kiểm bằng khóa công khai","intro":"Theo dõi cả thông điệp lẫn digest và điều kiện tin đúng public key.","nodes":[{"id":"m","slot":"a","label":"Thông điệp m","caption":"Nội dung cần ký","definition":"Thông điệp được biểu diễn thành byte theo quy tắc của định dạng/giao thức."},{"id":"sign","slot":"b","label":"Ký với private key","caption":"Tạo chữ ký σ","definition":"Thuật toán ký chuẩn xử lý thông điệp/digest cùng khóa riêng; một số thuật toán cần ngẫu nhiên hoặc nonce đúng quy tắc."},{"id":"wire","slot":"c","label":"m và σ","caption":"Gửi người kiểm","definition":"Thông điệp không nhất thiết bí mật vì có chữ ký."},{"id":"key","slot":"d","label":"Public key đã tin","caption":"Gắn với danh tính","definition":"Cần xác minh quan hệ giữa danh tính người ký và khóa dùng để kiểm."},{"id":"verify","slot":"f","label":"Verify(pk,m,σ)","caption":"Hợp lệ / không","definition":"Thuật toán kiểm tra ràng buộc chữ ký với thông điệp và public key tương ứng."}],"edges":[{"id":"a","fromId":"m","toId":"sign","label":"1"},{"id":"b","fromId":"sign","toId":"wire","label":"2"},{"id":"c","fromId":"wire","toId":"verify","label":"3"},{"id":"d","fromId":"key","toId":"verify","label":"4"}],"steps":[{"title":"Khóa riêng tạo chữ ký","body":"Người ký giữ private key và dùng thuật toán chữ ký phù hợp. Hash thường tham gia để ràng buộc nội dung vào chữ ký, nhưng chi tiết tùy thuật toán. Không định nghĩa mọi chữ ký là “mã hóa digest bằng khóa riêng”: đó là lối ví von không đúng tổng quát.","edges":["a"]},{"title":"Thông điệp và chữ ký là hai dữ liệu liên quan","body":"Người nhận cần đúng nội dung đã ký để kiểm tra. Chữ ký không làm người ngoài mất khả năng đọc m. Muốn bí mật, còn cần cơ chế mã hóa phù hợp; ký và mã hóa giải quyết các yêu cầu khác nhau.","edges":["b"]},{"title":"Kiểm tra trên nội dung hiện có","body":"Người kiểm chạy Verify với m,σ và public key. Nếu nội dung bị sửa, chữ ký cũ thường không còn hợp lệ cho nội dung mới. Kết quả không hợp lệ có thể do nhiều nguyên nhân: sửa dữ liệu, sai khóa, sai định dạng hoặc chữ ký không đúng.","edges":["c"]},{"title":"Xác minh đúng chủ thể của public key","body":"Một chữ ký hợp lệ với khóa do đối phương tự cung cấp chỉ chứng minh quan hệ toán học với khóa đó. Cần chuỗi chứng chỉ/nguồn tin khóa và chính sách phù hợp để gắn nó với người mong đợi. Khả năng chống chối bỏ còn phụ thuộc quản lý khóa, thời điểm và bằng chứng liên quan.","edges":["d"]}],"example":"Bạn nhận hợp đồng và chữ ký. Kiểm tra chữ ký bằng public key lấy từ nguồn đáng tin; nếu dùng khóa công khai được đính kèm nhưng chưa kiểm chứng danh tính, bạn có thể đang xác nhận chữ ký của người khác.","limits":"Hình là luồng khái niệm, không thay quy tắc ký số của RSA-PSS, ECDSA hoặc thuật toán cụ thể; cũng không tự kết luận giá trị pháp lý.","mistakes":["Public key dùng kiểm chữ ký, không phải bí mật được chia sẻ.","Chữ ký hợp lệ không đồng nghĩa nội dung là đúng sự thật."],"check":{"question":"Một tài liệu nói sai sự thật nhưng được chính người viết ký thì chữ ký có thể hợp lệ không?","answer":"Có. Chữ ký ràng buộc nội dung với khóa ký; nó không kiểm chứng chân lý của nội dung."},"refs":[],"deep":[]},{"id":"pki","chapter":"6","section":"6.2","title":"PKI: vì sao bạn tin một public key thuộc đúng máy chủ?","intro":"Đi từ cấp chứng chỉ đến kiểm tra đường tin cậy; chữ ký CA chỉ là một trong các điều kiện.","nodes":[{"id":"subject","slot":"a","label":"Chủ thể","caption":"Giữ private key","definition":"Chủ thể sở hữu cặp khóa; yêu cầu chứng chỉ chứa public key và thông tin cần xác minh."},{"id":"ra","slot":"b","label":"RA / xác minh","caption":"Kiểm tra yêu cầu","definition":"Registration Authority hoặc quy trình CA kiểm tra danh tính/quyền kiểm soát theo chính sách cấp."},{"id":"ca","slot":"c","label":"CA","caption":"Ký chứng chỉ","definition":"Certification Authority ký cấu trúc ràng buộc thông tin chủ thể với public key."},{"id":"cert","slot":"f","label":"Chứng chỉ X.509","caption":"Khóa + thông tin + ký","definition":"Chứng chỉ có tên, thời hạn, mục đích sử dụng và các trường cần kiểm tra, không chứa private key của chủ thể."},{"id":"client","slot":"e","label":"Bên kiểm tra","caption":"Trust anchor cục bộ","definition":"Bên kiểm cần điểm tin cậy và quy tắc kiểm chuỗi, không tự tin mọi CA bất kỳ."}],"edges":[{"id":"a","fromId":"subject","toId":"ra","label":"1"},{"id":"b","fromId":"ra","toId":"ca","label":"2"},{"id":"c","fromId":"ca","toId":"cert","label":"3"},{"id":"d","fromId":"cert","toId":"client","label":"4"}],"steps":[{"title":"Yêu cầu cấp không phải tự chứng minh danh tính","body":"Chủ thể tạo hoặc quản lý cặp khóa và đề nghị CA xác nhận public key. Việc có một cặp khóa mới chỉ chứng minh có khả năng mật mã tương ứng; còn cần chứng minh danh tính hoặc quyền kiểm soát tên theo chính sách của CA.","edges":["a"]},{"title":"Xác minh trước khi ký","body":"RA/quy trình CA kiểm tra thông tin mà CA dự định chứng nhận. Không suy ra mọi chứng chỉ đều xác minh cùng mức thông tin: xác minh quyền kiểm soát tên miền khác với xác minh toàn bộ uy tín, tính hợp pháp hoặc nội dung website.","edges":["b"]},{"title":"Chứng chỉ là bản ràng buộc được ký","body":"CA ký cấu trúc chứa public key và thông tin liên quan. Chứng chỉ có thể công khai; private key của chủ thể không được gửi kèm trong chứng chỉ. Nếu CA trung gian được dùng, bên nhận còn cần xây dựng đường tới trust anchor mà mình tin.","edges":["c"]},{"title":"Bên dùng kiểm nhiều điều kiện","body":"Kiểm chữ ký từng liên kết, ràng buộc CA, thời hạn, tên máy chủ, key usage/purpose và trạng thái thu hồi theo chính sách. Một chữ ký toán học hợp lệ nhưng sai hostname hoặc hết hạn vẫn không phải chứng chỉ phù hợp để chấp nhận kết nối đó.","edges":["d"]}],"example":"Bạn vào portal.example và nhận chứng chỉ có tên khác. Dù chữ ký CA hợp lệ, kiểm tra tên vẫn phải thất bại cho kết nối này. Nếu private key bị lộ, chủ thể cần xử lý thu hồi/thay khóa và chứng chỉ theo quy trình.","limits":"Sơ đồ gộp RA vào một khâu; một CA có thể tự làm việc xác minh. Chi tiết CRL/OCSP, trust store và lỗi mạng phụ thuộc chính sách bên dùng.","mistakes":["Chứng chỉ không chứa private key của website.","Chứng chỉ không chứng nhận mọi nội dung website là an toàn."],"check":{"question":"Tại sao chứng chỉ tự ký chưa tự tạo được niềm tin từ người lạ?","answer":"Vì chữ ký chỉ tự ràng buộc với chính khóa đó; người nhận vẫn cần một lý do độc lập để tin khóa và danh tính."},"refs":[],"deep":[{"title":"Xây đường chứng chỉ khác với tin mọi khóa gửi đến","body":"Leaf certificate của máy chủ có thể do intermediate CA ký; intermediate lại được một CA khác chứng nhận, đi đến trust anchor mà bên kiểm đã có lý do tin. Bên kiểm xác minh từng chữ ký và các ràng buộc đường dẫn/mục đích, không chỉ nối những tên giống nhau. Trust anchor không trở nên đáng tin chỉ vì nó tự ký; việc được cấu hình/trao tin ban đầu mới là cơ sở."},{"title":"Nếu private key bị lộ thì sao?","body":"Người sở hữu phải xử lý thay khóa/chứng chỉ và thu hồi theo quy trình, đồng thời đánh giá các phiên/dữ liệu chịu ảnh hưởng. CRL hoặc OCSP là cơ chế thông báo trạng thái theo triển khai; không tự xóa khóa đã bị đánh cắp khỏi máy đối phương, cũng không tự làm bí mật trở lại những dữ liệu đã bị đọc."}]},{"id":"ipsec","chapter":"6","section":"6.3","title":"IPsec tunnel: gói bên trong được bọc bởi gói bên ngoài","intro":"Theo một gói từ chi nhánh A sang B và phân biệt dữ liệu gốc với header dùng định tuyến qua Internet.","nodes":[{"id":"a","slot":"a","label":"Máy tại LAN A","caption":"Gói IP gốc","definition":"Nguồn và đích bên trong thuộc hai mạng cần kết nối."},{"id":"ga","slot":"b","label":"Gateway A","caption":"Chính sách IPsec","definition":"Gateway quyết định bypass, discard hoặc protect dựa chính sách."},{"id":"gb","slot":"c","label":"Gateway B","caption":"Kiểm và tháo bọc","definition":"Gateway đối tác nhận gói IPsec, kiểm tính hợp lệ và chuyển gói bên trong."},{"id":"b","slot":"f","label":"Máy tại LAN B","caption":"Nhận gói gốc","definition":"Đầu nhận cuối không nhất thiết tự chạy IPsec trong mô hình site-to-site này."},{"id":"ike","slot":"e","label":"IKE & SA","caption":"Thỏa thuận bảo vệ","definition":"Internet Key Exchange thiết lập thông số/khóa; Security Association ghi trạng thái bảo vệ cho một chiều."}],"edges":[{"id":"a","fromId":"a","toId":"ga","label":"1 · IP gốc"},{"id":"b","fromId":"ga","toId":"gb","label":"2 · tunnel"},{"id":"c","fromId":"gb","toId":"b","label":"3 · IP gốc"},{"id":"d","fromId":"ike","toId":"ga","label":"4 · SA"},{"id":"e","fromId":"ike","toId":"gb","label":"4 · SA"}],"steps":[{"title":"Chính sách chọn loại xử lý","body":"Không phải mọi gói tự động được mã hóa vì gateway hỗ trợ IPsec. Bộ chính sách xác định lưu lượng nào bỏ qua, loại bỏ hoặc phải bảo vệ. Nếu cần bảo vệ, thông số của SA và định tuyến phải phù hợp với luồng.","edges":["a"]},{"title":"Tunnel thêm lớp địa chỉ ngoài","body":"Gói IP gốc được giữ làm dữ liệu bên trong. Với ESP tunnel có mã hóa, nó được bảo vệ trong phần payload theo bộ thuật toán đã chọn; header IP mới chứa địa chỉ gateway để mạng trung gian định tuyến. Router Internet không cần đọc địa chỉ IP bên trong để chuyển lớp gói ngoài.","edges":["b"]},{"title":"Đầu kia kiểm trước khi sử dụng","body":"Gateway B xác định SA, kiểm tính toàn vẹn/xác thực và chống replay theo cấu hình, giải mã khi có mã hóa, rồi kiểm chính sách cho gói bên trong. Gói không hợp lệ không được chuyển vào LAN chỉ vì nó có header trông giống IPsec.","edges":["c"]},{"title":"Phân biệt mặt điều khiển và dữ liệu","body":"IKE thương lượng/xác thực và tạo trạng thái khóa; ESP/AH xử lý lưu lượng theo SA. Một SA IPsec là một chiều, nên liên lạc hai chiều cần các SA tương ứng. AH không cung cấp bí mật nội dung; ESP có dịch vụ theo cấu hình, không chỉ có duy nhất một cách dùng.","edges":["d","e"]}],"example":"Gói trong: máy LAN A → máy LAN B. Gói ngoài: gateway A → gateway B. Đổi sang transport mode thì không bọc toàn bộ gói gốc theo cùng cách; vì vậy không dùng hình tunnel để mô tả cả hai mode.","limits":"Hình chọn site-to-site ESP tunnel có mã hóa để minh họa. Không khẳng định mọi IPsec đều mã hóa mọi header, hay bảo vệ cả đoạn LAN trước và sau gateway.","mistakes":["Header ngoài còn cần cho định tuyến.","VPN tới gateway không tự bảo vệ dữ liệu trên mọi đoạn trong LAN."],"check":{"question":"Người quan sát Internet có thể thấy địa chỉ gateway dù payload được mã hóa không?","answer":"Có. Header ngoài phục vụ định tuyến vẫn lộ các thông tin tương ứng."},"refs":["https://www.rfc-editor.org/info/rfc4301/"],"deep":[]},{"id":"tls","chapter":"6","section":"6.4","title":"TLS 1.3: thỏa thuận, xác thực, rồi bảo vệ dữ liệu","intro":"Mô hình một kết nối đầy đủ dùng chứng chỉ máy chủ và trao đổi khóa tạm thời; không trộn với sơ đồ SSL/RSA cũ.","nodes":[{"id":"client","slot":"a","label":"Client","caption":"ClientHello","definition":"Đầu khởi tạo đề xuất tham số, gửi giá trị trao đổi khóa công khai theo nhóm đã chọn."},{"id":"server","slot":"c","label":"Server","caption":"ServerHello","definition":"Máy chủ chọn tham số tương thích và gửi phần trao đổi khóa của mình."},{"id":"verify","slot":"d","label":"Client xác minh","caption":"Chứng chỉ & transcript","definition":"Client kiểm danh tính máy chủ, chữ ký ràng buộc handshake và thông điệp xác nhận."},{"id":"records","slot":"f","label":"Kênh ứng dụng","caption":"Khóa lưu lượng","definition":"Hai phía dùng các khóa lưu lượng riêng cho từng chiều và AEAD để bảo vệ record."}],"edges":[{"id":"a","fromId":"client","toId":"server","label":"1 · Hello"},{"id":"b","fromId":"server","toId":"client","label":"2 · Hello"},{"id":"c","fromId":"server","toId":"verify","label":"3 · xác thực"},{"id":"d","fromId":"verify","toId":"records","label":"4 · dữ liệu"}],"steps":[{"title":"Đề xuất và chọn tham số","body":"ClientHello gửi các khả năng mà client hỗ trợ và dữ liệu trao đổi khóa công khai. ServerHello chọn tổ hợp phù hợp, không phải tùy ý chọn một thuật toán client không biết. Trong mô hình trao đổi khóa tạm thời, hai bên tính bí mật chung cục bộ, không gửi private exponent.","edges":["a"]},{"title":"Dẫn xuất các khóa theo giai đoạn","body":"Kết quả trao đổi khóa và thông tin handshake đi vào lịch dẫn xuất khóa. TLS 1.3 dùng khóa handshake trước khi chuyển sang khóa ứng dụng; không có một khóa duy nhất dùng bất biến cho mọi mục đích. Các thông điệp sau ServerHello được bảo vệ theo quy tắc giao thức.","edges":["b"]},{"title":"Kiểm đúng máy chủ và toàn bộ cuộc trao đổi","body":"Client kiểm chứng chỉ, tên đích và các điều kiện PKI. CertificateVerify chứng minh sở hữu khóa riêng tương ứng và ràng buộc với transcript handshake; Finished xác nhận khóa và tính toàn vẹn transcript. Chỉ kiểm “chứng chỉ có chữ ký” mà bỏ các kiểm tra khác là thiếu.","edges":["c"]},{"title":"Trao đổi ứng dụng bằng khóa đối xứng","body":"Sau các xác nhận bắt buộc, record ứng dụng được bảo vệ bằng AEAD, kết hợp bí mật và kiểm tra toàn vẹn với thông tin liên quan. Các khóa cho hai chiều khác nhau. TLS không tự kiểm chứng website có nội dung trung thực hoặc máy đầu cuối có sạch malware không.","edges":["d"]}],"example":"Trình duyệt truy cập cổng học tập: đầu tiên thỏa thuận và xác thực, sau đó mới gửi dữ liệu ứng dụng trong kênh bảo vệ. Biểu tượng HTTPS không có nghĩa chủ website không lừa đảo.","limits":"Chọn nhánh full handshake có chứng chỉ; chưa vẽ PSK, resumption, client authentication, HelloRetryRequest hoặc 0-RTT. Không áp thứ tự TLS 1.3 cho mọi phiên bản SSL/TLS trong slide.","mistakes":["TLS 1.3 không dùng mô hình gửi premaster secret bằng RSA tĩnh như một số sơ đồ TLS cũ.","Mã hóa kênh không thay xác minh danh tính endpoint."],"check":{"question":"Tại sao cần CertificateVerify ngoài việc gửi chứng chỉ?","answer":"Vì gửi chứng chỉ công khai chưa chứng minh bên đang handshake nắm private key tương ứng và đã ràng buộc nó với cuộc trao đổi này."},"refs":["https://www.rfc-editor.org/info/rfc9846/"],"deep":[{"title":"Transcript và khóa cho từng mục đích","body":"Transcript là bản ghi mật mã của các thông điệp handshake theo quy tắc TLS. Dẫn xuất bằng HKDF gắn khóa với bí mật và ngữ cảnh, phân biệt khóa handshake/ứng dụng và hai chiều gửi. CertificateVerify ràng buộc quyền sở hữu khóa ký vào ngữ cảnh handshake; Finished dùng khóa xác nhận để kiểm transcript. Đây là hai kiểm tra liên quan nhưng không đồng nhất."},{"title":"AEAD bảo vệ record ra sao?","body":"AEAD nhận khóa, nonce, plaintext và dữ liệu liên quan để tạo ciphertext/tag. Phần liên quan được xác thực nhưng không nhất thiết mã hóa. Đầu nhận chỉ được sử dụng plaintext theo quy tắc sau khi xác minh hợp lệ; đổi bit ciphertext hoặc thông tin liên quan được bảo vệ sẽ làm kiểm tra tag thất bại với xác suất giả mạo bị giới hạn. Quy tắc nonce/sequence number của giao thức là một phần của an toàn, không phải chi tiết có thể bỏ qua."}]},{"id":"hybrid-mail","chapter":"6","section":"6.5","title":"Email mã hóa lai: dữ liệu dùng khóa phiên, khóa phiên dùng public key","intro":"Giải thích vì sao ghép hai loại mật mã thay vì mã hóa mọi byte bằng RSA.","nodes":[{"id":"mail","slot":"a","label":"Nội dung email","caption":"Thông điệp dài","definition":"Nội dung và tệp đính kèm cần bảo vệ trước khi vận chuyển/lưu ở các máy trung gian."},{"id":"session","slot":"d","label":"Khóa phiên K","caption":"Sinh cho thông điệp","definition":"Khóa ngẫu nhiên đối xứng được dùng trong cơ chế mã hóa nội dung."},{"id":"content","slot":"b","label":"Bản mã nội dung","caption":"Mã hóa đối xứng","definition":"Phần dữ liệu lớn được bảo vệ bằng thuật toán/chế độ nội dung phù hợp."},{"id":"wrap","slot":"e","label":"Bảo vệ K","caption":"Public key của Bob","definition":"Một cơ chế bất đối xứng/hybrid chuẩn bảo vệ khóa nội dung cho người nhận."},{"id":"package","slot":"c","label":"Gói gửi","caption":"Bản mã + khóa bảo vệ","definition":"Gói chứa dữ liệu đã mã hóa cùng thông tin cho người nhận lấy lại khóa."},{"id":"bob","slot":"f","label":"Bob mở gói","caption":"Private key → K → m","definition":"Khóa riêng cho phép lấy lại khóa nội dung rồi giải mã thông điệp theo định dạng."}],"edges":[{"id":"a","fromId":"session","toId":"content","label":"1 · K mới"},{"id":"b","fromId":"mail","toId":"content","label":"2 · m"},{"id":"c","fromId":"session","toId":"wrap","label":"3"},{"id":"d","fromId":"content","toId":"package","label":"4"},{"id":"e","fromId":"wrap","toId":"package","label":"4"},{"id":"f","fromId":"package","toId":"bob","label":"5"}],"steps":[{"title":"Tạo khóa nội dung","body":"Chọn khóa đối xứng K phù hợp và các tham số theo cơ chế đã chọn. “Khóa phiên” trong hình nói khóa nội dung của gói minh họa, không khẳng định mọi định dạng email dùng cùng một cấu trúc khóa.","edges":["a"]},{"title":"Mã hóa phần lớn dữ liệu bằng đối xứng","body":"Mật mã đối xứng phù hợp xử lý khối lượng dữ liệu lớn. Cần mode/định dạng bảo vệ đúng; không chỉ thay tên thuật toán là đủ. Các dịch vụ toàn vẹn/xác thực phụ thuộc cơ chế được dùng.","edges":["b"]},{"title":"Bảo vệ khóa cho từng người nhận","body":"Dùng khóa công khai đã xác minh của Bob để bảo vệ khả năng truy xuất K theo chuẩn. Với nhiều người nhận, gói có thể mang nhiều thông tin khóa riêng cho từng người thay vì mã hóa lại toàn bộ nội dung theo một public key duy nhất.","edges":["c"]},{"title":"Gửi gói và giải theo thứ tự ngược","body":"Bob dùng khóa riêng để khôi phục khóa nội dung, rồi dùng khóa đó xử lý phần bản mã. Nếu khóa riêng không đúng người nhận hoặc thông tin khóa bị hỏng, việc biết ciphertext nội dung không đủ mở thư. Các kiểm tra tính hợp lệ của định dạng phải được thực hiện.","edges":["d","e","f"]},{"title":"Ký số là một mục tiêu bổ sung","body":"Mã hóa cho public key Bob không chứng minh Alice đã gửi: ai có public key Bob cũng có thể tạo thư mã hóa gửi Bob. Muốn xác thực người gửi cần chữ ký/cơ chế phù hợp và tin đúng khóa ký. Thứ tự ký, nén, đóng gói tùy PGP/S/MIME và phiên bản.","edges":["f"]}],"example":"Một tệp lớn dùng một khóa nội dung; thông tin cho Bob lấy khóa có kích thước nhỏ hơn nhiều so với tệp. Bob cần khóa riêng của mình để lấy K, không cần private key của Alice để giải nội dung.","limits":"Là mô hình mã hóa lai chung, không phải đặc tả byte hoặc thứ tự đầy đủ mọi phiên bản PGP/S/MIME. Không tự triển khai theo hình.","mistakes":["Public key người nhận phục vụ bí mật cho người nhận.","Private key người gửi phục vụ ký, không chia sẻ cho người nhận."],"check":{"question":"Thư chỉ được mã hóa cho Bob đã đủ chứng minh Alice viết thư chưa?","answer":"Chưa. Mã hóa cho Bob và xác thực Alice là hai yêu cầu khác nhau."},"refs":[],"deep":[]},{"id":"kerberos","chapter":"6","section":"6.6","title":"Kerberos: đổi vé thay vì gửi mật khẩu cho mọi dịch vụ","intro":"Theo ba cuộc trao đổi: AS, TGS và dịch vụ; phân biệt vé với authenticator.","nodes":[{"id":"as","slot":"a","label":"AS","caption":"Authentication Server","definition":"Thành phần KDC hỗ trợ bước xác thực ban đầu và cấp Ticket-Granting Ticket."},{"id":"tgs","slot":"c","label":"TGS","caption":"Ticket-Granting Server","definition":"Thành phần KDC dùng TGT hợp lệ để cấp vé cho một dịch vụ cụ thể."},{"id":"client","slot":"d","label":"Client","caption":"Giữ khóa phiên tạm","definition":"Client có cơ chế xác thực ban đầu, sau đó dùng vé và khóa phiên phù hợp."},{"id":"server","slot":"f","label":"Dịch vụ SS","caption":"Kiểm vé dịch vụ","definition":"Application server có khóa dài hạn phù hợp để mở vé dành cho chính nó."}],"edges":[{"id":"a","fromId":"client","toId":"as","label":"1 · AS-REQ"},{"id":"b","fromId":"as","toId":"client","label":"2 · TGT"},{"id":"c","fromId":"client","toId":"tgs","label":"3 · TGS-REQ"},{"id":"d","fromId":"tgs","toId":"client","label":"4 · vé SS"},{"id":"e","fromId":"client","toId":"server","label":"5 · AP-REQ"},{"id":"f","fromId":"server","toId":"client","label":"6 · AP-REP"}],"steps":[{"title":"Xác thực ban đầu với AS","body":"Client yêu cầu bước AS theo cơ chế Kerberos và pre-authentication được cấu hình. Không mô tả đây là gửi mật khẩu bản rõ trên mạng. AS cần có cách xác minh theo phương thức dùng trước khi cấp phản hồi phù hợp.","edges":["a"]},{"title":"Nhận TGT và khóa client–TGS","body":"Phản hồi chứa TGT được bảo vệ cho TGS và phần cho client lấy khóa phiên client–TGS. Client không cần tự giải mã nội dung TGT để mang nó đi sử dụng. TGT là vé xin vé dịch vụ, chưa phải vé cho mọi ứng dụng tùy ý.","edges":["b"]},{"title":"Dùng TGT xin vé cho SS","body":"Client gửi TGT, yêu cầu dịch vụ và authenticator bảo vệ bằng khóa phiên client–TGS. Authenticator chứng minh phía trình vé biết khóa phiên và cung cấp thông tin mới theo giao thức; chỉ sao chép vé không đồng nghĩa có đủ mọi điều kiện dùng vé.","edges":["c"]},{"title":"TGS trả vé và khóa client–SS","body":"TGS kiểm yêu cầu rồi cấp vé dành cho SS, được bảo vệ bằng khóa mà SS có thể dùng để mở. Client nhận khóa phiên client–SS qua phần phản hồi được bảo vệ cho mình. Khóa này khác với khóa client–TGS.","edges":["d"]},{"title":"Trình vé dịch vụ và xác nhận hai chiều","body":"Client gửi vé SS và authenticator tương ứng. SS kiểm vé, thời hạn, authenticator và replay theo quy tắc; nếu yêu cầu xác thực hai chiều, SS trả AP-REP chứng minh nắm khóa phiên. Đồng bộ thời gian, replay cache và bảo vệ khóa vẫn quan trọng.","edges":["e","f"]}],"example":"Bạn đăng nhập một lần rồi mở dịch vụ được phép trong miền Kerberos. Dịch vụ nhận vé cho nó, không cần nhận mật khẩu của bạn mỗi lần. Có vé hợp lệ cũng chưa thay chính sách phân quyền của dịch vụ.","limits":"AS và TGS thường là vai trò trong KDC, không bắt buộc hai máy vật lý. Hình mô tả luồng Kerberos V5 cơ bản, bỏ chi tiết realm, delegation và cơ chế pre-auth cụ thể.","mistakes":["TGT khác vé dịch vụ.","Vé và authenticator khác nhau.","Kerberos cơ bản không phải hệ dùng public key để mã hóa mọi vé."],"check":{"question":"Vì sao không trình TGT trực tiếp để thay mọi service ticket?","answer":"TGT dành cho TGS; service ticket được tạo cho đúng SS và có cấu trúc bảo vệ để SS đó xử lý."},"refs":["https://www.rfc-editor.org/info/rfc4120/"],"deep":[{"title":"Ai mở được vé nào? — nhánh khóa đối xứng minh họa","body":"Ký hiệu Kc,tgs là khóa phiên client–TGS, Kc,ss là khóa phiên client–dịch vụ. TGT được bảo vệ bằng khóa dài hạn của TGS và mang Kc,tgs cùng thông tin vé; client cầm TGT nhưng không cần tự mở nó. Phần AS trả cho client được bảo vệ theo cơ chế xác thực ban đầu, trong nhánh mật khẩu cơ bản liên quan khóa dài hạn của client. Service ticket được bảo vệ cho SS và chứa Kc,ss; phần phản hồi TGS cho client được bảo vệ bằng Kc,tgs. Tên khóa không chỉ tên máy gửi packet mà chỉ quan hệ bảo vệ."},{"title":"Vé khác authenticator ở tính mới","body":"Vé có thời hạn để tái sử dụng theo quy tắc, còn authenticator được client tạo mới bằng khóa phiên tương ứng và mang thông tin như thời điểm để server kiểm. Nếu chỉ trình lại nguyên một yêu cầu cũ, kiểm replay/timestamp và replay cache phải giúp loại nó. Nếu cả vé lẫn khóa phiên bị đánh cắp, rủi ro khác với việc chỉ nhìn thấy vé trên đường truyền; vì vậy phải bảo vệ cache/khóa trên đầu cuối."}]},{"id":"ssh","chapter":"6","section":"6.7","title":"SSH: xác thực máy chủ trước, rồi người dùng, rồi mở kênh","intro":"Ba lớp chức năng của SSH không được nhập thành một bước “gõ mật khẩu”.","nodes":[{"id":"client","slot":"a","label":"SSH client","caption":"Khởi tạo kết nối","definition":"Ứng dụng phía người dùng muốn dùng dịch vụ máy chủ qua kênh bảo vệ."},{"id":"host","slot":"b","label":"Host key & KEX","caption":"Danh tính máy chủ","definition":"Trao đổi khóa tạo bí mật phiên; chữ ký/kiểm host key giúp ràng buộc đúng máy chủ."},{"id":"transport","slot":"c","label":"Transport bảo vệ","caption":"Mã hóa & toàn vẹn","definition":"Các tham số/khóa được dùng để bảo vệ luồng SSH sau thương lượng."},{"id":"user","slot":"f","label":"User authentication","caption":"Đúng tài khoản","definition":"Máy chủ kiểm người dùng bằng phương thức được cho phép, ví dụ khóa công khai."},{"id":"channels","slot":"e","label":"Connection channels","caption":"Shell / forwarding","definition":"SSH multiplex nhiều kênh logic trong một kết nối theo quyền và chính sách."}],"edges":[{"id":"a","fromId":"client","toId":"host","label":"1"},{"id":"b","fromId":"host","toId":"transport","label":"2"},{"id":"c","fromId":"transport","toId":"user","label":"3"},{"id":"d","fromId":"user","toId":"channels","label":"4"}],"steps":[{"title":"Kiểm máy chủ trong trao đổi khóa","body":"Host key gắn với máy chủ, khác khóa xác thực tài khoản của người dùng. Kênh tin cậy trước hoặc cơ chế quản lý khóa cho biết bạn đang tin khóa của ai. Cùng IP hoặc cổng 22 mở chưa chứng minh đúng danh tính.","edges":["a"]},{"title":"Thiết lập transport an toàn","body":"Hai bên thương lượng thuật toán và thiết lập khóa bảo vệ kênh. KEX không có nghĩa gửi private key của người dùng qua mạng. Nếu chấp nhận nhầm host key, bạn vẫn có thể có kết nối được mã hóa nhưng tới sai chủ thể.","edges":["b"]},{"title":"Xác thực người dùng bên trong kênh","body":"Server kiểm phương thức mà chính sách cho phép. Với public-key authentication, client chứng minh sở hữu khóa riêng tương ứng, không gửi nguyên khóa riêng cho server. Thành công chỉ xác nhận tài khoản theo cơ chế đó; quyền làm gì là vấn đề tiếp theo.","edges":["c"]},{"title":"Mở kênh theo nhu cầu và quyền","body":"Connection protocol tạo shell, chạy lệnh hoặc các loại kênh được cho phép. Một kết nối có thể có nhiều kênh, nhưng không có nghĩa mọi chức năng forwarding hoặc mọi quyền hệ thống đều tự được cấp. Giới hạn phiên và quyền vẫn phải cấu hình.","edges":["d"]}],"example":"SSH báo host key thay đổi: xác minh qua kênh đáng tin trước khi chấp nhận. Không bỏ qua chỉ vì vẫn đăng nhập được hoặc IP không đổi.","limits":"Mô hình SSH-2 tổng quát; chưa vẽ từng packet, rekey hay từng phương thức xác thực. Host key không phải chứng chỉ web X.509 mặc định.","mistakes":["Khóa host khác khóa tài khoản.","Mã hóa không tự chứng minh đúng host nếu bỏ kiểm khóa."],"check":{"question":"Vì sao khóa riêng người dùng không cần được gửi cho server để public-key authentication hoạt động?","answer":"Vì client tạo bằng chứng mật mã để server kiểm bằng khóa công khai tương ứng, thay vì tiết lộ bí mật."},"refs":[],"deep":[]},{"id":"otp","chapter":"3","section":"3.3.4","title":"One-time Pad: vì sao tái sử dụng khóa phá vỡ điều kiện?","intro":"Nhìn hai thông điệp khi dùng chung pad; tính an toàn mạnh của OTP có những điều kiện rất chặt.","nodes":[{"id":"m1","slot":"a","label":"Thông điệp m₁","caption":"Chuỗi bit","definition":"Thông điệp thứ nhất được biểu diễn thành bit."},{"id":"k","slot":"b","label":"Pad K","caption":"Ngẫu nhiên, dùng một lần","definition":"Pad đúng nghĩa phải ngẫu nhiên độc lập, bí mật, dài ít nhất phần dữ liệu cần mã hóa và không dùng lại."},{"id":"c1","slot":"c","label":"c₁ = m₁ ⊕ K","caption":"Bản mã thứ nhất","definition":"XOR từng bit thông điệp với pad tạo ciphertext."},{"id":"m2","slot":"d","label":"Thông điệp m₂","caption":"Nếu dùng lại cùng K","definition":"Nhánh dưới cố tình vi phạm điều kiện một lần để chỉ ra hậu quả."},{"id":"c2","slot":"e","label":"c₂ = m₂ ⊕ K","caption":"Bản mã thứ hai","definition":"Hai bản mã khi dùng chung K có quan hệ mà người ngoài tính được."},{"id":"leak","slot":"f","label":"c₁ ⊕ c₂ = m₁ ⊕ m₂","caption":"Pad bị triệt tiêu","definition":"Lộ quan hệ giữa hai plaintext; không còn lập luận bí mật hoàn hảo của OTP đúng điều kiện."}],"edges":[{"id":"a","fromId":"m1","toId":"k","label":"1"},{"id":"b","fromId":"k","toId":"c1","label":"2"},{"id":"c","fromId":"m2","toId":"c2","label":"3 · dùng lại K"},{"id":"d","fromId":"c2","toId":"leak","label":"4"},{"id":"e","fromId":"c1","toId":"leak","label":"4"}],"steps":[{"title":"OTP đúng nghĩa bắt đầu bằng pad đúng điều kiện","body":"K không chỉ là một mật khẩu được lặp lại cho đủ dài. Ngẫu nhiên, độc lập với thông điệp, bí mật, đủ dài và dùng đúng một lần là những điều kiện cốt lõi. Nếu thay pad ngẫu nhiên bằng luồng sinh từ khóa ngắn, đó là mô hình an toàn khác.","edges":["a"]},{"title":"Mã hóa và giải mã bằng XOR","body":"c=m⊕K; người có K tính c⊕K=m vì K⊕K=0. Cách tính đơn giản không có nghĩa việc quản lý pad đơn giản: hai bên phải phân phối và sử dụng cùng đoạn pad mà không để lộ hoặc tái dùng.","edges":["b"]},{"title":"Xét nhánh sai: tái sử dụng một đoạn pad","body":"Nếu c₁=m₁⊕K và c₂=m₂⊕K, người quan sát có thể XOR hai ciphertext mà không biết K. Khi đó K xuất hiện hai lần và bị triệt tiêu. Không được tiếp tục gọi đây là OTP đúng điều kiện bảo mật.","edges":["c"]},{"title":"Thông tin lộ là quan hệ giữa plaintext","body":"c₁⊕c₂=m₁⊕m₂. Điều này chưa tự cung cấp riêng từng thông điệp, nhưng làm lộ quan hệ và có thể kết hợp với cấu trúc/ngữ cảnh hoặc một plaintext đã biết để suy ra thông điệp kia. OTP cũng không tự cung cấp xác thực: bit ciphertext bị lật gây tác động có cấu trúc lên plaintext.","edges":["d","e"]}],"example":"m₁=1010, m₂=1100, K=0110 → c₁=1100, c₂=1010. c₁⊕c₂=0110=m₁⊕m₂. Các chuỗi chỉ 4 bit để tính tay, không phải khóa dùng thực tế.","limits":"Nhánh dưới là phản ví dụ dùng sai khóa, không phải cách vận hành hợp lệ của OTP. Hình không chứng minh mọi mật mã dòng đều bị phá giống nhau.","mistakes":["“Dùng một lần” áp dụng cho đoạn pad, không phải chỉ tên ứng dụng.","Bí mật không đồng nghĩa toàn vẹn."],"check":{"question":"Biết m₁ và c₁,c₂ trong nhánh dùng chung K có thể suy ra m₂ như thế nào?","answer":"Tính m₂=c₁⊕c₂⊕m₁. Đây là hậu quả của việc tái sử dụng cùng đoạn pad."},"refs":[],"deep":[]},{"id":"wifi-4way","chapter":"7","section":"7.4","title":"WPA2-Personal: bốn thông điệp không gửi mật khẩu qua sóng","intro":"PMK có trước; four-way handshake chứng minh biết khóa và tạo khóa theo phiên.","nodes":[{"id":"pmk","slot":"b","label":"PMK có trước","caption":"Từ PSK phù hợp","definition":"Pairwise Master Key được có từ cấu hình khóa/phương thức tương ứng; ví dụ passphrase WPA2-Personal dùng dẫn xuất có SSID."},{"id":"sta","slot":"d","label":"Station","caption":"Máy người dùng","definition":"Thiết bị muốn kết nối AP, giữ bí mật cần thiết để tham gia thiết lập khóa."},{"id":"ap","slot":"f","label":"Access Point","caption":"Điểm truy cập","definition":"AP tham gia four-way handshake và quản lý khóa cho liên kết."},{"id":"keys","slot":"h","label":"PTK / GTK","caption":"Unicast / group","definition":"Pairwise Transient Key phục vụ cặp STA–AP; Group Temporal Key phục vụ lưu lượng nhóm theo cơ chế."}],"edges":[{"id":"p","fromId":"pmk","toId":"sta","label":"PMK"},{"id":"q","fromId":"pmk","toId":"ap","label":"PMK"},{"id":"a","fromId":"ap","toId":"sta","label":"1 · ANonce"},{"id":"b","fromId":"sta","toId":"ap","label":"2 · SNonce+MIC"},{"id":"c","fromId":"ap","toId":"sta","label":"3 · MIC, GTK"},{"id":"d","fromId":"sta","toId":"ap","label":"4 · xác nhận"},{"id":"e","fromId":"sta","toId":"keys","label":"khóa"},{"id":"f","fromId":"ap","toId":"keys","label":"khóa"}],"steps":[{"title":"Trước handshake phải có bí mật nền","body":"Trong ví dụ WPA2-Personal dùng passphrase, hai phía tạo PMK theo quy tắc có passphrase và SSID. SSID không phải bí mật; biết tên mạng không cho biết passphrase. Four-way handshake không bắt đầu bằng việc gửi mật khẩu cho AP.","edges":["p","q"]},{"title":"Thông điệp 1: AP gửi ANonce","body":"AP đưa một giá trị nonce và thông tin điều khiển để bắt đầu lần thiết lập. STA có PMK, tạo SNonce và có các địa chỉ MAC cần thiết để dẫn xuất PTK. MAC ở “địa chỉ MAC” khác MAC trong “Message Authentication Code”.","edges":["a"]},{"title":"Thông điệp 2: STA gửi SNonce và MIC","body":"STA gửi SNonce cùng MIC, tức mã kiểm tra toàn vẹn của bản tin theo khóa con phù hợp. AP dùng thông tin nhận được để dẫn xuất PTK và kiểm MIC. Hai bên không phải gửi nguyên PTK hoặc PMK để chứng minh có cùng bí mật.","edges":["b"]},{"title":"Thông điệp 3: AP xác nhận và phân phối khóa nhóm","body":"Bản tin được bảo vệ về toàn vẹn và có dữ liệu khóa nhóm được bảo vệ theo quy tắc. STA kiểm MIC, thông tin lần trao đổi và cài khóa đúng trạng thái. Không hiểu “có GTK trong bản tin” là GTK được phát công khai dạng không bảo vệ.","edges":["c"]},{"title":"Thông điệp 4: xác nhận hoàn tất","body":"STA phản hồi xác nhận bằng bản tin có MIC. Sau khi hoàn tất các điều kiện thiết lập, hai phía dùng khóa cho lưu lượng phù hợp. Một passphrase dễ đoán vẫn có thể dẫn đến rủi ro đoán khóa ngoại tuyến từ dữ liệu handshake đã có; điều đó khác với mật khẩu được gửi nguyên văn.","edges":["d","e","f"]}],"example":"Hai máy biết cùng mật khẩu mạng không nhất thiết dùng cùng khóa unicast theo phiên: nonce và địa chỉ tham gia dẫn xuất PTK. Biết SSID đơn thuần không đủ giải nội dung.","limits":"Chọn WPA2-Personal; không gộp WPA3-SAE hoặc mọi biến thể Enterprise vào cùng sơ đồ. Chưa vẽ mọi trường, replay counter và chi tiết cài khóa; sơ đồ không hướng dẫn thu thập handshake.","mistakes":["PMK, PTK, GTK là các vai trò khóa khác nhau.","Four-way handshake không gửi passphrase.","Mã hóa liên kết Wi-Fi không tự là mã hóa đầu cuối tới website."],"check":{"question":"Nếu không gửi passphrase, vì sao passphrase yếu vẫn nguy hiểm?","answer":"Vì dữ liệu kiểm chứng từ một phiên có thể cho phép thử ứng viên ngoại tuyến trong điều kiện phù hợp; không cần thấy mật khẩu nguyên văn."},"refs":[],"deep":[{"title":"PMK, PTK, KCK, KEK và TK nối nhau thế nào?","body":"Viết sơ đồ ý niệm: PTK=KDF(PMK, địa chỉ AP, địa chỉ STA, ANonce, SNonce), với cách sắp xếp/định dạng chính xác theo chuẩn. PTK gồm các phần có vai trò riêng: KCK dùng cho MIC của trao đổi khóa; KEK bảo vệ thông tin khóa như việc chuyển GTK; TK dùng cho bảo vệ dữ liệu unicast theo cipher. GTK là khóa nhóm do AP quản lý, không đồng nghĩa toàn bộ PTK. Đây là sơ đồ vai trò, không phải công thức đủ để tự triển khai KDF."},{"title":"Wi-Fi và HTTPS bảo vệ hai đoạn khác nhau","body":"Bảo vệ WPA2 liên kết thiết bị–AP không mặc nhiên kéo dài tới máy chủ Internet. AP là một đầu của bảo vệ liên kết và còn chuyển dữ liệu đi tiếp. TLS có thể tạo lớp bảo vệ giữa ứng dụng client và server qua cả AP. Ghép hai lớp không thừa: mỗi lớp có phạm vi tin cậy và điểm kết thúc khác nhau."}]},{"id":"enterprise","chapter":"7","section":"7.3","title":"802.1X / EAP-TLS: AP gác cổng, server xác thực danh tính","intro":"Phân biệt ba vai trò và hai giai đoạn: EAP xác thực trước, four-way handshake sau.","nodes":[{"id":"sta","slot":"a","label":"Supplicant","caption":"Máy người dùng","definition":"Thiết bị có phần mềm EAP và thông tin xác thực, ví dụ chứng chỉ client trong EAP-TLS."},{"id":"ap","slot":"b","label":"Authenticator","caption":"AP / thiết bị gác cổng","definition":"Điểm truy cập điều khiển quyền đi qua cổng dữ liệu, chuyển thông điệp EAP tới backend."},{"id":"server","slot":"c","label":"Authentication server","caption":"Backend EAP / RADIUS","definition":"Hệ thống kiểm danh tính và chính sách theo EAP method, thường được tích hợp với RADIUS."},{"id":"keys","slot":"f","label":"Vật liệu khóa","caption":"Dẫn xuất theo chuẩn","definition":"Kết quả phương thức EAP thành công tạo cơ sở cho các khóa của liên kết; không phải phát mật khẩu cho mọi người."},{"id":"port","slot":"e","label":"Liên kết được mở","caption":"Vẫn có phân quyền","definition":"Thiết lập khóa và chính sách truy cập hoàn tất trước khi cho lưu lượng tương ứng."}],"edges":[{"id":"a","fromId":"sta","toId":"ap","label":"1 · EAPOL"},{"id":"b","fromId":"ap","toId":"server","label":"2 · backend"},{"id":"c","fromId":"server","toId":"keys","label":"3 · thành công"},{"id":"d","fromId":"keys","toId":"port","label":"4 · khóa/port"}],"steps":[{"title":"AP chưa cho mọi dữ liệu đi qua","body":"Authenticator cho phép các trao đổi cần để xác thực theo cơ chế trước khi mở quyền truy cập dữ liệu thông thường. Có thể nhìn thấy một SSID và kết nối vô tuyến không đồng nghĩa đã có quyền vào mọi dịch vụ trong LAN.","edges":["a"]},{"title":"Chọn một EAP method cụ thể để hiểu","body":"Với ví dụ EAP-TLS, client và server dùng chứng chỉ theo phương thức để xác thực. AP chuyển các trao đổi giữa supplicant và backend; nó không đơn giản so một mật khẩu chung cho cả lớp. Client phải kiểm đúng danh tính/chứng chỉ server theo cấu hình.","edges":["b"]},{"title":"Thành công tạo cơ sở thiết lập khóa","body":"Vật liệu khóa từ phương thức được dùng theo quy tắc của hệ thống để thiết lập PMK tương ứng. AP nhận thông tin cần cho vai trò của mình qua backend được bảo vệ theo triển khai, không phải mọi máy cùng nhận private key của client.","edges":["c"]},{"title":"Four-way handshake và chính sách mở truy cập","body":"Sau EAP thành công, STA và AP còn thiết lập khóa liên kết, chẳng hạn bằng four-way handshake trong WPA2-Enterprise. Danh tính riêng cho phép thu hồi một người hoặc áp chính sách riêng, nhưng hiệu quả phụ thuộc quản trị chứng chỉ, tài khoản và cấu hình thật.","edges":["d"]}],"example":"Một nhân viên rời nhóm: thu hồi credential cá nhân và cập nhật quyền dễ quản lý hơn đổi một mật khẩu chia sẻ cho toàn bộ người dùng. Không suy ra mọi hệ Enterprise đều dùng EAP-TLS; đây chỉ là nhánh được chọn để giải thích.","limits":"RADIUS là backend thường gặp, không phải tên khác của EAP. Các EAP method có cơ chế/thuộc tính khác nhau; hình cố định EAP-TLS để tránh đánh đồng.","mistakes":["AP authenticator khác authentication server.","EAP thành công không có nghĩa mọi quyền ứng dụng đều được cấp."],"check":{"question":"AP có phải luôn tự kiểm mật khẩu người dùng thay server không?","answer":"Không. Trong mô hình này nó điều khiển truy cập và chuyển EAP tới backend xác thực."},"refs":[],"deep":[]},{"id":"stateful","chapter":"8","section":"8.2.3","title":"Stateful firewall: vì sao gói phản hồi được phép quay vào?","intro":"Theo một kết nối TCP được chính sách cho phép; bảng trạng thái không phải danh sách mọi gói “an toàn”.","nodes":[{"id":"lan","slot":"a","label":"Client LAN","caption":"Khởi tạo TCP","definition":"Máy trong mạng gửi SYN đến server theo đích/cổng đã chọn."},{"id":"rules","slot":"b","label":"Rule & state","caption":"Quyết định firewall","definition":"Luật cho biết kết nối mới nào được phép; trạng thái lưu diễn biến luồng được theo dõi."},{"id":"server","slot":"c","label":"Server ngoài","caption":"SYN-ACK / dữ liệu","definition":"Server phản hồi theo ngữ cảnh phiên TCP."},{"id":"state","slot":"e","label":"Bảng trạng thái","caption":"Tuple, trạng thái, timeout","definition":"Thông tin luồng gồm địa chỉ, cổng, giao thức và trạng thái liên quan theo triển khai."},{"id":"return","slot":"d","label":"Client nhận","caption":"Phản hồi hợp lệ","definition":"Gói quay vào được xét dựa chính sách và trạng thái, không vì mọi gói từ ngoài đều được tin."}],"edges":[{"id":"a","fromId":"lan","toId":"rules","label":"1 · SYN"},{"id":"b","fromId":"rules","toId":"server","label":"2 · cho qua"},{"id":"c","fromId":"rules","toId":"state","label":"3 · ghi state"},{"id":"d","fromId":"server","toId":"state","label":"4 · phản hồi"},{"id":"e","fromId":"state","toId":"return","label":"5 · khớp"}],"steps":[{"title":"Kết nối mới vẫn phải qua rule","body":"Firewall nhận SYN từ LAN và xét chính sách áp dụng. Stateful không có nghĩa client bên trong được phép mở mọi đích. Nếu chính sách chặn, không được tạo một đường vào chỉ vì gói phát từ LAN.","edges":["a"]},{"title":"Tạo trạng thái cho luồng được phép","body":"Khi luồng được chấp nhận, hệ thống theo dõi tuple và diễn biến theo khả năng triển khai. Tuple thường liên quan địa chỉ nguồn/đích, cổng nguồn/đích và giao thức. Cổng nguồn của client là một phần của việc phân biệt nhiều kết nối.","edges":["b","c"]},{"title":"Đối chiếu gói phản hồi","body":"SYN-ACK hoặc dữ liệu trở về được so với luồng theo dõi, chiều truyền, trạng thái và các kiểm tra giao thức phù hợp. Không phải chỉ nhìn một bit ACK rồi mặc định cho qua. Kết quả còn chịu quy tắc và cách tracking của firewall.","edges":["d"]},{"title":"Không khớp hoặc hết hạn thì xét như luồng khác","body":"Gói không thuộc luồng hợp lệ không được hưởng quyền “phản hồi” của luồng trước. Khi kết nối đóng hoặc timeout, trạng thái bị loại theo quy tắc. Dù luồng hợp lệ, nội dung ứng dụng vẫn có thể độc hại nếu không có lớp kiểm tra phù hợp.","edges":["e"]}],"example":"Client 192.168.1.10:51514 nối server:443. Gói trả về đúng phiên có thể được cho qua, còn một kết nối mới không được yêu cầu từ Internet vào cổng khác vẫn bị chặn theo chính sách minh họa.","limits":"Không vẽ NAT hoặc mọi cờ TCP/sequence number. Stateful không bảo đảm xác thực người dùng hay phát hiện mọi tấn công trong ứng dụng.","mistakes":["Stateful khác chỉ lọc packet độc lập.","Có state không nghĩa mọi byte của phiên lành tính."],"check":{"question":"Gói có ACK nhưng không thuộc phiên theo dõi có tự được cho qua không?","answer":"Không. Quyết định phải dựa chính sách và ngữ cảnh trạng thái, không chỉ tên một cờ."},"refs":[],"deep":[]},{"id":"pat","chapter":"8","section":"8.3","title":"PAT: nhiều máy dùng một địa chỉ ngoài nhờ bảng ánh xạ","intro":"Đi cả chiều gửi lẫn chiều trả lời để hiểu vai trò của cổng, không gộp NAT với firewall.","nodes":[{"id":"lan","slot":"a","label":"192.168.1.10:51514","caption":"Nguồn trong LAN","definition":"Địa chỉ/cổng nguồn của một kết nối trước dịch địa chỉ."},{"id":"nat","slot":"b","label":"Thiết bị PAT","caption":"Sửa địa chỉ & cổng","definition":"Port Address Translation ánh xạ tuple nội bộ sang tuple bên ngoài."},{"id":"internet","slot":"c","label":"198.51.100.20:443","caption":"Server đích","definition":"Server nhìn thấy nguồn là tuple đã dịch, không phải địa chỉ private ban đầu."},{"id":"map","slot":"e","label":"Bảng ánh xạ","caption":"51514 ↔ 40001","definition":"Ví dụ gắn 192.168.1.10:51514 với 203.0.113.7:40001 trong ngữ cảnh kết nối."},{"id":"reply","slot":"d","label":"Máy LAN nhận lại","caption":"Dịch ngược","definition":"Gói về được ánh xạ lại đến nguồn nội bộ theo trạng thái và chính sách."}],"edges":[{"id":"a","fromId":"lan","toId":"nat","label":"1"},{"id":"b","fromId":"nat","toId":"internet","label":"2 · nguồn mới"},{"id":"c","fromId":"nat","toId":"map","label":"3 · mapping"},{"id":"d","fromId":"internet","toId":"map","label":"4 · trả lời"},{"id":"e","fromId":"map","toId":"reply","label":"5 · dịch ngược"}],"steps":[{"title":"Gói ban đầu có cả nguồn và đích","body":"Client gửi từ 192.168.1.10:51514 đến 198.51.100.20:443. Địa chỉ IP cho biết máy/mạng; cổng hỗ trợ phân biệt điểm giao tiếp transport. Chỉ ghi địa chỉ IP mà bỏ cổng sẽ không đủ mô tả ví dụ PAT này.","edges":["a"]},{"title":"Thay tuple nguồn ra ngoài","body":"PAT chọn nguồn ngoài 203.0.113.7:40001 và điều chỉnh các trường liên quan theo cơ chế. Server đích phản hồi đến nguồn mà nó thấy. Nội dung ứng dụng không vì NAT mà tự được mã hóa.","edges":["b"]},{"title":"Lưu cách tìm về nguồn gốc","body":"Bảng ghi quan hệ giữa tuple nội bộ và bên ngoài cùng thông tin cần cho kiểu mapping/luồng. Nhiều máy có thể dùng cùng IP ngoài với cổng ngoài khác nhau; không có nghĩa chúng trở thành một tiến trình hoặc một người dùng duy nhất.","edges":["c"]},{"title":"Đổi đích của gói về và kiểm chính sách","body":"Gói trả về gửi tới 203.0.113.7:40001. Thiết bị tra ánh xạ phù hợp và chuyển đích lại thành 192.168.1.10:51514. Khi mapping hết hạn hoặc không tồn tại, nó không có cơ sở chuyển theo ánh xạ này. Việc cho phép vẫn khác với chính chức năng dịch.","edges":["d","e"]}],"example":"Một máy khác có thể có nguồn trong LAN khác nhưng cùng dùng 203.0.113.7 với cổng ngoài khác. Các IP ngoài trong ví dụ là địa chỉ tài liệu, không phải máy thật để thử kết nối.","limits":"Hình chọn source PAT động. NAT tĩnh, DNAT/port forwarding và các loại mapping khác có hành vi riêng; không suy ra mọi NAT chặn mọi kết nối vào.","mistakes":["NAT không phải mã hóa.","Dịch địa chỉ không tự thay chính sách firewall."],"check":{"question":"Vì sao chỉ biết IP ngoài chưa đủ xác định máy LAN nhận gói trả lời?","answer":"Vì nhiều tuple nội bộ có thể chia sẻ IP ngoài; cần cổng/giao thức và ngữ cảnh mapping phù hợp."},"refs":[],"deep":[]},{"id":"dmz","chapter":"8","section":"8.4","title":"DMZ: công khai dịch vụ mà vẫn giữ ranh giới LAN","intro":"Không chỉ vẽ ba vùng: hãy đọc luật cho từng chiều và từng dịch vụ.","nodes":[{"id":"net","slot":"a","label":"Internet","caption":"Nguồn không tin cậy","definition":"Nơi người dùng công khai truy cập dịch vụ được công bố."},{"id":"outer","slot":"b","label":"Kiểm soát ngoài","caption":"Chỉ luồng cần thiết","definition":"Có thể là giao diện/vùng của firewall hoặc thiết bị riêng theo kiến trúc."},{"id":"web","slot":"c","label":"Web server DMZ","caption":"Dịch vụ công khai","definition":"Máy chủ phải nhận một số kết nối Internet nhưng không được xem như hoàn toàn tin cậy."},{"id":"inner","slot":"f","label":"Kiểm soát DMZ–LAN","caption":"Quyền tối thiểu","definition":"Chỉ cho luồng được yêu cầu rõ giữa dịch vụ DMZ và tài nguyên bên trong."},{"id":"db","slot":"e","label":"Database LAN","caption":"Không công khai trực tiếp","definition":"Cơ sở dữ liệu được tách khỏi truy cập trực tiếp từ Internet trong ví dụ."},{"id":"admin","slot":"d","label":"Quản trị tin cậy","caption":"Đường quản trị riêng","definition":"Điểm quản trị phải chịu xác thực, phân quyền và kiểm soát đường vào theo thiết kế."}],"edges":[{"id":"a","fromId":"net","toId":"outer","label":"1"},{"id":"b","fromId":"outer","toId":"web","label":"2 · HTTPS"},{"id":"c","fromId":"web","toId":"inner","label":"3 · yêu cầu DB"},{"id":"d","fromId":"inner","toId":"db","label":"4 · đúng luồng"},{"id":"e","fromId":"admin","toId":"db","label":"5 · quản trị"}],"steps":[{"title":"Internet chỉ tới dịch vụ công khai","body":"Luật ngoài cho phép luồng cần thiết, ví dụ HTTPS đến đúng web server DMZ. Không mở cùng cổng đó tới mọi host hoặc coi có DMZ là có thể bỏ kiểm tra server công khai. Server này vẫn cần vá lỗi và gia cố.","edges":["a","b"]},{"title":"DMZ được coi là vùng có thể bị xâm hại","body":"Nếu web server bị chiếm, ranh giới trong phải giới hạn nó có thể tiếp cận những gì. DMZ không làm server bất khả xâm nhập; giá trị của nó là giảm tin cậy và cô lập ảnh hưởng so với đặt thẳng dịch vụ công khai trong LAN.","edges":["c"]},{"title":"Chỉ cấp luồng backend cần thiết","body":"Nếu ứng dụng cần DB, mở đúng nguồn web, đúng đích DB, giao thức/cổng và chiều theo nhu cầu. Kết nối đã cho phép vẫn có thể mang truy vấn độc hại nếu web bị chiếm, nên cần tài khoản DB ít quyền và kiểm soát ứng dụng.","edges":["d"]},{"title":"Tách đường quản trị và giám sát","body":"Luồng quản trị không nên được mở tùy ý từ Internet vì tiện. Thiết kế đường tin cậy, xác thực mạnh, ghi log và kiểm soát quyền phù hợp. “Không có mũi tên Internet→DB” trong hình biểu đạt chính sách mong muốn, không tự tạo ra luật trên thiết bị.","edges":["e"]}],"example":"Cho Internet→Web:443. Cho Web→DB chỉ khi ứng dụng thực sự cần và đúng cổng đã xác định. Không cho Web→mọi host LAN. Nếu DB chỉ cần quyền đọc cho chức năng đó, không cấp quyền quản trị DB.","limits":"Hai hộp kiểm soát là hai ranh giới logic; có thể dùng một firewall nhiều vùng hoặc nhiều thiết bị. Mũi tên biểu diễn luồng được chọn để giải thích, không liệt kê mọi lưu lượng DNS, cập nhật hay phản hồi.","mistakes":["DMZ không phải vùng hoàn toàn đáng tin.","Rule DMZ→LAN any làm suy yếu mục đích phân tách."],"check":{"question":"Nếu web DMZ bị chiếm, lớp DMZ–LAN còn có ích gì?","answer":"Nó có thể giới hạn đường tiếp cận sang LAN, giảm phạm vi tác động; nhưng phải kết hợp quyền backend và kiểm soát khác."},"refs":[],"deep":[]},{"id":"proxy","chapter":"8","section":"8.2.4","title":"Proxy: hai kết nối thay vì chuyển một kết nối nguyên vẹn","intro":"Theo điểm kết thúc phiên và phân biệt chuyển tiếp với kiểm tra nội dung TLS.","nodes":[{"id":"client","slot":"a","label":"Client","caption":"Kết nối tới proxy","definition":"Client gửi yêu cầu cho proxy theo cơ chế cấu hình/triển khai."},{"id":"proxy","slot":"b","label":"Proxy ứng dụng","caption":"Nhận và quyết định","definition":"Proxy xử lý yêu cầu theo giao thức mà nó hỗ trợ và áp chính sách."},{"id":"server","slot":"c","label":"Server đích","caption":"Kết nối từ proxy","definition":"Trong mô hình proxy kết thúc phiên, server thấy kết nối do proxy tạo."},{"id":"policy","slot":"e","label":"Chính sách / log","caption":"Danh tính, đích, nội dung","definition":"Khả năng kiểm tra thực tế phụ thuộc proxy có nhìn được dữ liệu nào và có được phép xử lý chúng không."}],"edges":[{"id":"a","fromId":"client","toId":"proxy","label":"1 · phiên A"},{"id":"b","fromId":"proxy","toId":"server","label":"2 · phiên B"},{"id":"c","fromId":"server","toId":"proxy","label":"3 · phản hồi"},{"id":"d","fromId":"proxy","toId":"client","label":"4 · trả về"},{"id":"e","fromId":"proxy","toId":"policy","label":"kiểm tra"}],"steps":[{"title":"Client không nhất thiết kết nối trực tiếp server","body":"Trong mô hình này, phiên transport/ứng dụng của client kết thúc tại proxy. Proxy có thể nhận danh tính client, kiểm đích hoặc áp quy tắc giao thức. Đây khác với một router chỉ quyết định next hop của gói.","edges":["a"]},{"title":"Proxy tạo một phiên riêng tới đích","body":"Proxy đóng vai client đối với server. Hai phiên có trạng thái riêng; nó không chỉ viết lại một trường IP như mô hình PAT. Tuy vậy cách dùng từ “proxy” rộng: reverse proxy và forward proxy có hướng phục vụ khác nhau.","edges":["b"]},{"title":"Phản hồi đi qua điểm kiểm soát","body":"Proxy nhận phản hồi từ server, có thể áp chính sách phù hợp rồi gửi về client. Khả năng xem nội dung tùy giao thức và cấu hình. Một đường hầm HTTPS CONNECT không tự đồng nghĩa proxy đọc được plaintext HTTP bên trong TLS.","edges":["c","d"]},{"title":"Muốn kiểm tra TLS phải có mô hình tin cậy khác","body":"Nếu một hệ thống kết thúc và thiết lập lại TLS để kiểm tra nội dung, nó tạo hai quan hệ TLS và cần cấu hình tin cậy/quyền phù hợp ở client. Không được đánh đồng với chuyển tiếp TLS nguyên vẹn. Cần mô tả rõ proxy nhìn được gì trước khi kết luận khả năng lọc.","edges":["e"]}],"example":"Forward proxy phục vụ người dùng ra Internet; reverse proxy đứng trước dịch vụ phục vụ khách. Cả hai có thể áp chính sách nhưng không vì tên gọi mà tự thấy mọi nội dung đã mã hóa.","limits":"Hình chọn proxy ứng dụng kết thúc phiên; chưa mô tả mọi kiểu tunneling, transparent proxy hoặc cache. Không suy ra mọi proxy đều giải mã TLS.","mistakes":["Proxy không đồng nghĩa NAT.","CONNECT tunnel khác TLS inspection."],"check":{"question":"Tại sao một proxy chuyển đường hầm HTTPS chưa chắc chặn được một từ trong trang?","answer":"Vì nó có thể không có plaintext ứng dụng để kiểm tra từ đó; chỉ thấy thông tin của lớp/kênh mà nó quan sát được."},"refs":[],"deep":[]}];
